    end
    IS = 1.2 * Iload_A;
    IS_SEC = IS / CTR;
    unit = 'A-primary';
    basis = 'above-full-load-below-min-fault:1.2xFL_anchor-LINE_Q9-0.869956651959241kA-from-phase4_ct_data.csv-via-1600/1';
    source = ['DERIVED-study-setting:1.2xFL_anchor-LINE_Q9-0.869956651959241kA;' ...
        'SOURCE-BACKED-CT-1600/1-ledger-GIS-bay-1600/1;' ...
        'ENGINEERING_ASSUMPTION-TMS-0.20-ledger-TMS-0.20'];
    mLoad = IS / Iload_A;
    mFault = Imin_fault_A / IS;
    validation = sprintf(['no-trip-on-load-vs-FL_anchor-%.6fA(margin-%.3f);' ...
        'must-detect-vs-Imin-%.3fA(margin-%.3f);' ...
        'T7-converts-via-CT-1600/1'], ...
        Iload_A, mLoad, Imin_fault_A, mFault);
    P = struct('setting', IS, 'unit', unit, 'basis', basis, ...
