% === C4-IMPLEMENTED (Task C4: study rule branch above serves GEN-51/GEN-51-SI,
% GSUT-HV-51, GIS-Q0-51, GEN-51N/GEN-51N-SI-STUDY; GIS-Q0-50 DISABLED errors) ===

function E = phase5b_effectiveness(T40, devices)
%PHASE5B_EFFECTIVENESS  Primary/backup effectiveness table, mandatory review S15 (Phase-5b Task C8).
%   E = PHASE5B_EFFECTIVENESS(T40, devices) returns one table row per
%   backbone (caseID, fault_location, fault_type) study-backup row (40 rows)
%   plus one Siemens-baseline backup twin per F1 generator-zone row (8 rows),
%   i.e. 48 rows total. Locked columns (this order):
%     fault_location, fault_type, caseID, primary_function,
%     primary_availability, primary_time_s, backup_function, backup_time_s,
%     ct_source, setting_source, detection, determinable, not_determinable.
%   primary_availability / detection vocabulary is locked to
%   ASSERTABLE-DETECT / NOT-DETERMINABLE; determinable is logical and mirrors
%   detection; not_determinable always carries text (blocking or
%   residual-limitation reasons); ct_source / setting_source always carry
%   traceability text.
%
%   RUNTIME (binding carry-over 1): phase5b_branch_phasors(T40) is called
%   ONCE per invocation (takes ~5 min on the 40-row backbone: one frozen
%   phase4_contrib re-solve per row plus the 1e-6 identity gate against the
%   production contributions CSV). The resulting B table is reused across
%   all 48 rows below; no .mat caching (determinism first).
%
%   INWARD-FLOW JUSTIFICATION (locked detection rule): internal fault + max
%   terminal branch >= sourced pickup -> ASSERTABLE-DETECT; else
%   NOT-DETERMINABLE, never invented. Every B leg magnitude derives from the
%   frozen phase4_contrib legs re-signed TOWARD THE FAULT (phase4_contrib.m
%   header lines 20-35: every leg re-signed toward the fault, then
%   phase-reconstructed per leg with Fortescue), so at an internal fault
%   every zone terminal feeds inward and the differential sum is the
%   magnitude sum. GEN-87G detection is therefore assertable exactly when
%   the GEN terminal faulted-phase branch meets the sourced 87G pickup
%   (0.20 x 12019 = 2403.8 A from the GEN-87G registry row,
%   USER_ASSERTED_PENDING_DOC + master-S21 Status-C corroboration).
%   GSUT-87T carries presence only (7UT6331 settings missing, registry
%   pickup NaN) so its assertability rests on the master-S21 Status-C
%   transformer-differential starting assumption (ledger TR-DIFF-0.30pu,
%   ENGINEERING_ASSUMPTION) applied to the Siemens nameplate base:
%   start threshold 0.30 x Siemens nameplate HV rated current IN 1292.8 A
%   (Generator Data_South.pdf pp.6-7 S2.2.1: "Rated current IN 1.292,8 A"
%   -> 387.84 A), quoted in every F2 reason with provenance
%   label master-S21-Status-C-starting-assumption-applied-to-Siemens-nameplate-base.
%   GIS-87B / LINE-7SD carry
%   presence only with no sourced pickup anywhere (registry pickup NaN),
%   so they are always NOT-DETERMINABLE: the reason reports the kA-scale
%   inward magnitude observation (F3: GSUT_HV + LINE_total + GRID infeeds;
%   F4: LINE_B1 + LINE_B2 sections) with live values but asserts no
%   detection. Timing for 87T/87B/7SD always stays NaN (settings missing,
%   never 45 ms).
%
%   F4 DOCTRINE (binding carry-over 2): at F4 the B1/B2 leg rows are used,
%   never the LINE_total cancellation residual (~1e-13 kA at LL/LLG, where
%   the two toward-fault infeeds cancel in the unfaulted-phase sum). The
%   GIS-side backup current is the LINE_B1 GIS-side section outfeed.
%
%   BACKUP TIMES (binding carry-over 3): from the v2 study inputs (C4
%   pickups 1.20x14309 = 17170.8 A GEN-51-SI, 1380 A GSUT-HV-51, GIS
%   1.2x869.9567 A formula, 5 A GEN-51N-SI-STUDY; TMS 0.20 phase / 0.15 EF;
%   1600/1 study CTs) via the frozen phase5_time/phase5_curve library
%   (read-only use; settings obtained from phase5b_pickup, never
%   hard-coded). Faulted-phase branch magnitudes come from B
%   (Ibranch_faulted_A: maxABC at LLL, Ia at LG, maxBC at LL/LLG); the only
%   T40 magnitude column read is the NER series leg (leg_NER_earth_kA),
%   whose neutral current has I1 = I2 = 0 so its |Ia| serves all phases and
%   3x gives the 3I0 residual exactly (F1 LG sensitivity scope). Fault-point
%   totals are never a proxy for relay current. Siemens-baseline backup
%   rows (DT-??) respect use_phase5_time == false: backup_time NaN with the
%   ?? pending-coordination reason, never dispatched to the frozen
%   operating-time entry point.
%
%   PRIMARY TIME (binding carry-over 4): 0.045 s derived fast-main clearing
%   ONLY where 87-class detection is assertable AND the interrupting breaker
%   is identified (F1/87G + GEN-52G GCB 10BAC10 100 kA) -- else NaN with a
%   reason; 87T timing NaN (0.30pu start assumption only, 7UT6331 settings
%   missing); 7SD/87B timing NaN (no sourced pickup, settings missing).
%
%   GEN LLG RESIDUAL (binding carry-over 5): the C6 out-of-51N-scope note
%   (F1-LLG OUT 3I0 3.638 A observed; 51N study basis is LG-only) appears in
%   every LLG row's not_determinable text with the live 3xNER quote.
%
%   Backup mapping: F1+LG -> GEN-51N-SI-STUDY (EF; phase element honestly
%   blind there per C6); F1 otherwise -> GEN-51-SI; F2 -> GSUT-HV-51;
%   F3/F4/F5 -> GIS-Q0-51 (F4 via LINE_B1, F3/F5 via LINE_total through
%   convention). F5 (remote, out-of-zone, no zone primary mapped) is always
%   NOT-DETERMINABLE with a remote-backup time.
%
%   All errors are 'phase5b'-prefixed.
if nargin ~= 2
    error('phase5b_effectiveness:args', 'usage: E = phase5b_effectiveness(T40, devices).');
end
if ~istable(T40) || height(T40) < 1
    error('phase5b_effectiveness:schema', 'T40 must be a non-empty table (phase5_import backbone).');
end
needCols = {'fault_location', 'fault_type', 'caseID', 'leg_NER_earth_kA'};
for k = 1:numel(needCols)
    if ~any(strcmp(T40.Properties.VariableNames, needCols{k}))
        error('phase5b_effectiveness:schema', 'T40 missing required column %s.', needCols{k});
    end
end
if ~isstruct(devices) || isempty(devices) || ~isfield(devices, 'device_id')
    error('phase5b_effectiveness:devices', 'devices must be a non-empty struct array with device_id (registry rows).');
end

% --- Single branch-phasor recompute (~5 min); rows below reuse B. ---
B = phase5b_branch_phasors(T40);

% --- Sourced references from the registry (never hard-coded pickups). ---
d87 = devrow(devices, 'GEN-87G');
if ~isfield(d87, 'pickup_A') || ~isfinite(d87.pickup_A)
    error('phase5b_effectiveness:pickup', 'GEN-87G registry row must carry the sourced 0.20pu start pickup (never invented).');
end
IS87 = double(d87.pickup_A);  % 0.20 x 12019 = 2403.8 A
has52G = ~isempty(findDevice(devices, 'GEN-52G'));
genD = reqdev(devices, 'GEN-51');
efD = reqdev(devices, 'GEN-51N');
gsutD = reqdev(devices, 'GSUT-HV-51');
gisD = reqdev(devices, 'GIS-Q0-51');
blD = reqdev(devices, 'GEN-51-SIEMENS-BL');
d87T = devrow(devices, 'GSUT-87T');  % presence only; 87T threshold base is the Siemens nameplate IN below, never the registry study rating
GSUT_HV_BASE_A = 1292.8;  % Siemens nameplate HV rated current IN (Generator Data_South.pdf pp.6-7 S2.2.1: "Rated current IN 1.292,8 A"); master-S21-Status-C-starting-assumption applied to Siemens nameplate base
TRDIFF_START_PU = 0.30;  % ledger TR-DIFF-0.30pu transformer-differential bias/start (ENGINEERING_ASSUMPTION)
I87T_START_A = TRDIFF_START_PU * GSUT_HV_BASE_A;  % 0.30 x 1292.8 = 387.84 A start threshold (never a relay setting)
ILOAD_GEN = 14309;              % ledger GEN-Imax-14309 (C4 basis)
ILOAD_GSUT = 870.772573866956;  % GSUT_HV flow anchor (rule takes max with rated 1150 A)
ILOAD_GIS = 869.956651959241;   % LINE_Q9 flow anchor from ct_data FL_anchor

floc = cell(0, 1); ftyp = cell(0, 1); cids = cell(0, 1);
pfunc = cell(0, 1); pavail = cell(0, 1); ptime = zeros(0, 1);
bfunc = cell(0, 1); btime = zeros(0, 1);
ctsrc = cell(0, 1); setsrc = cell(0, 1); det = cell(0, 1);
determ = false(0, 1); ndet = cell(0, 1);

n = height(T40);
for i = 1:n
    loc = aschar(T40.fault_location(i));
    typ = aschar(T40.fault_type(i));
    cs = aschar(T40.caseID(i));
    ner = double(T40.leg_NER_earth_kA(i));  % kA, finite only at LG/LLG

    % === PRIMARY (zone-mapped; detection-vs-timing split) ===
    switch loc
        case 'F1'
            pf = 'GEN-87G';
            gI = bget(B, cs, loc, typ, 'GEN');
            if isfinite(gI) && gI >= IS87
                pa = 'ASSERTABLE-DETECT';
                if has52G
                    tp = 0.045;  % derived fast-main clearing: 87G + 52G/10BAC10 identified
                    tNote = sprintf(['primary-87G-ASSERTABLE-DETECT-GEN-terminal-%.1fA->=' ...
                        'sourced-pickup-0.20x12019-%.1fA;' ...
                        'primary_time-0.045s-derived-fast-main-clearing-87G-plus-' ...
                        'breaker-52G-10BAC10-100kA-identified'], gI, IS87);
                else
                    tp = NaN;
                    tNote = sprintf(['primary-87G-ASSERTABLE-DETECT-GEN-terminal-%.1fA;' ...
                        'primary_time-NaN-breaker-52G-not-identified-trip-matrix-' ...
                        'NOT-DETERMINABLE'], gI);
                end
                psrc = ['USER_ASSERTED_PENDING_DOC:SIEMENS-87G-0.20-START-' ...
                    'PENDING-DOC-INGEST-master-S21-Status-C-corroborated'];
                cts = ['SOURCE-BACKED:GEN-T1T2-15000/1-3cores-' ...
                    'ledger-GEN-T1T2-15000-primary-CT'];
            else
                pa = 'NOT-DETERMINABLE';
                tp = NaN;
                tNote = sprintf(['primary-87G-NOT-DETERMINABLE-GEN-terminal-%.3gA-' ...
                    'below-sourced-pickup-%.1fA-or-missing;' ...
                    'primary_time-NaN-no-assertable-detection'], gI, IS87);
                psrc = ['USER_ASSERTED_PENDING_DOC:SIEMENS-87G-0.20-START-' ...
                    'PENDING-DOC-INGEST-master-S21-Status-C-corroborated'];
                cts = ['SOURCE-BACKED:GEN-T1T2-15000/1-3cores-' ...
                    'ledger-GEN-T1T2-15000-primary-CT'];
            end
        case 'F2'
            pf = 'GSUT-87T';
            aI = bget(B, cs, loc, typ, 'GEN');
            bI = bget(B, cs, loc, typ, 'GSUT_HV');
            psrc = ['SOURCE-BACKED:PROT-7UT6331-presence-settings-MISSING-' ...
                'ledger-TR-DIFF-0.30pu-0.30pu-start-ENGINEERING_ASSUMPTION-' ...
                'master-S21-Status-C-starting-assumption-applied-to-Siemens-' ...
                'nameplate-base-HV-IN-1292.8A-Generator-Data-South-pp6-7-S2.2.1-' ...
                'differential-timing-NOT-DETERMINABLE'];
            cts = ['SOURCE-BACKED:GSUT-HV-1600/1-cores-HV-' ...
                'ledger-GSUT-1600/1-cores-plus-GEN-T1T2-15000/1-differential-terminals'];
            if isfinite(aI) && isfinite(bI) && aI >= I87T_START_A && bI >= I87T_START_A
                pa = 'ASSERTABLE-DETECT';
                tp = NaN;
                tNote = sprintf(['primary-GSUT-87T-ASSERTABLE-DETECT-internal-' ...
                    'transformer-fault-inward-GEN-%.1fA-plus-GSUT_HV-%.1fA-' ...
                    'vs-start-0.30pu-x-Siemens-nameplate-HV-base-%.1fA-=%.2fA-' ...
                    'master-S21-Status-C-starting-assumption-applied-to-Siemens-' ...
                    'nameplate-base-ledger-TR-DIFF-0.30pu;' ...
                    'primary_time-NaN-GSUT-87T-7UT6331-settings-missing-' ...
                    'timing-NOT-DETERMINABLE-never-45ms'], aI, bI, GSUT_HV_BASE_A, I87T_START_A);
            else
                pa = 'NOT-DETERMINABLE';
                tp = NaN;
                tNote = sprintf(['primary-GSUT-87T-NOT-DETERMINABLE-vs-start-' ...
                    '0.30pu-x-Siemens-nameplate-HV-base-%.1fA-=%.2fA-' ...
                    'master-S21-Status-C-starting-assumption-applied-to-Siemens-' ...
                    'nameplate-base-ledger-TR-DIFF-0.30pu-' ...
                    'inward-GEN-%.3gA-GSUT_HV-%.3gA;' ...
                    'primary_time-NaN-GSUT-87T-settings-missing'], GSUT_HV_BASE_A, I87T_START_A, aI, bI);
            end
        case 'F3'
            pf = 'GIS-87B';
            aI = bget(B, cs, loc, typ, 'GSUT_HV');
            bI = bget(B, cs, loc, typ, 'LINE_total');
            cI = bget(B, cs, loc, typ, 'GRID');
            psrc = ['SOURCE-BACKED:PROT-7SS523-presence-settings-MISSING-' ...
                'differential-timing-NOT-DETERMINABLE'];
            cts = ['SOURCE-BACKED:GIS-bay-1600/1-5P20-30VA-' ...
                'ledger-GIS-bay-1600/1-study-CT'];
            % No sourced 7SS523 pickup exists (registry pickup NaN): never assert;
            % the reason below reports the live inward magnitudes with no detection.
            pa = 'NOT-DETERMINABLE';
            tp = NaN;
            tNote = sprintf(['primary-GIS-87B-NOT-DETERMINABLE-no-sourced-' ...
                '7SS523-pickup-registry-pickup-NaN-presence-only-kA-scale-' ...
                'magnitude-observation-inward-GSUT_HV-%.1fA-plus-LINE-%.1fA-' ...
                'plus-GRID-%.1fA-no-detection-asserted;' ...
                'primary_time-NaN-GIS-87B-7SS523-settings-missing-' ...
                'timing-NOT-DETERMINABLE-never-45ms'], aI, bI, cI);
        case 'F4'
            pf = 'LINE-7SD';
            aI = bget(B, cs, loc, typ, 'LINE_B1');
            bI = bget(B, cs, loc, typ, 'LINE_B2');
            psrc = ['SOURCE-BACKED:PROT-7SD5221x2-2x7SD5221-presence-' ...
                'settings-MISSING-differential-timing-NOT-DETERMINABLE'];
            cts = ['SOURCE-BACKED:GIS-bay-1600/1-5P20-30VA-' ...
                'ledger-GIS-bay-1600/1-study-CT'];
            % No sourced 7SD5221 pickup exists (registry pickup NaN): never assert;
            % the reason below reports the live section magnitudes with no detection.
            pa = 'NOT-DETERMINABLE';
            tp = NaN;
            tNote = sprintf(['primary-LINE-7SD-NOT-DETERMINABLE-no-sourced-' ...
                '7SD5221-pickup-registry-pickup-NaN-presence-only-kA-scale-' ...
                'magnitude-observation-inward-LINE_B1-GIS-side-%.1fA-plus-' ...
                'LINE_B2-remote-side-%.1fA-no-detection-asserted;' ...
                'primary_time-NaN-LINE-7SD-7SD5221x2-settings-missing-' ...
                'timing-NOT-DETERMINABLE-never-45ms'], aI, bI);
        otherwise  % F5: remote, out-of-zone, no zone primary mapped
            pf = 'NONE-no-zone-primary-mapped';
            pa = 'NOT-DETERMINABLE';
            tp = NaN;
            tNote = ['primary-NOT-DETERMINABLE-out-of-zone-F5-remote-grid-' ...
                'fault-no-zone-primary-mapped-no-87-class-in-zone;' ...
                'primary_time-NaN-no-primary-mapped'];
            psrc = 'NONE-no-zone-primary-mapped-out-of-zone-no-setting-source';
            cts = ['SOURCE-BACKED:GIS-bay-1600/1-5P20-30VA-' ...
                'ledger-GIS-bay-1600/1-study-CT'];
    end

    % === STUDY BACKUP (v2 C4 inputs via phase5b_pickup; frozen operating time) ===
    if strcmp(loc, 'F1') && strcmp(typ, 'LG')
        bf = 'GEN-51N-SI-STUDY';
        dev = efD;
        Iload = 0;
        I = 3 * ner * 1000;  % 3I0 from the NER series leg (LG sensitivity scope)
        scopeNote = sprintf(['backup-EF-5A-retained-sensitive-case-scope-' ...
            'SENSITIVITY-C4-LG-basis-must-detect-F1-LG-3I0-%.3fA;' ...
            'phase-element-blind-at-F1-LG-C6-EF-element-covers'], I);
    elseif strcmp(loc, 'F1')
        bf = 'GEN-51-SI';
        dev = genD;
        Iload = ILOAD_GEN;
        I = bget(B, cs, loc, typ, 'GEN');
        scopeNote = sprintf('backup-phase-GEN-terminal-faulted-phase-%.1fA', I);
    elseif strcmp(loc, 'F2')
        bf = 'GSUT-HV-51';
        dev = gsutD;
        Iload = ILOAD_GSUT;
        I = bget(B, cs, loc, typ, 'GSUT_HV');
        scopeNote = sprintf('backup-phase-GSUT_HV-terminal-faulted-phase-%.1fA', I);
    elseif strcmp(loc, 'F4')
        bf = 'GIS-Q0-51';
        dev = gisD;
        Iload = ILOAD_GIS;
        I = bget(B, cs, loc, typ, 'LINE_B1');  % GIS-side section outfeed, never the cancellation residual
        scopeNote = sprintf(['backup-via-LINE_B1-GIS-side-outfeed-%.1fA-' ...
            'NEVER-LINE_total-cancellation-residual'], I);
    else  % F3 / F5: through-convention outfeed
        bf = 'GIS-Q0-51';
        dev = gisD;
        Iload = ILOAD_GIS;
        I = bget(B, cs, loc, typ, 'LINE_total');
        scopeNote = sprintf('backup-via-LINE_total-through-convention-%.1fA', I);
    end
    if isfinite(I) && I > 0
        IminArg = I;
    else
        IminArg = 1;  % shapes validation text only; setting is load-based
    end
    P = phase5b_pickup(dev, Iload, IminArg);
    if ~P.use_phase5_time
        tb = NaN;
        bNote = [scopeNote ';backup_time-NaN-use_phase5_time-false-never-dispatched'];
    elseif isfinite(I) && I > 0
        tb = phase5_time(I, P.setting, P.tms, P.curve);
        bNote = sprintf([scopeNote '-vs-pickup-%.4fA-SI-TMS-%.2f-time-%.4fs-via-frozen-phase5_time'], ...
            P.setting, P.tms, tb);
    else
        tb = NaN;
        bNote = [scopeNote ';backup_time-NaN-backup-current-not-finite-or-missing-no-trip-invented'];
    end
    ssrc = ['primary:' psrc ' | backup:' P.source];

    % === LLG residual context (C6 out-of-51N-scope note, live quote) ===
    if strcmp(typ, 'LLG')
        if isfinite(ner)
            llgNote = sprintf(['GEN-LLG-residual-3I0-%.3fA-observed-' ...
                'out-of-51N-scope-C4-LG-basis-only-C6-OUT-anchor-3.638A'], 3 * ner * 1000);
        else
            llgNote = ['GEN-LLG-residual-NER-leg-unavailable-here-' ...
                'out-of-51N-scope-C4-LG-basis-only-C6-OUT-anchor-3.638A'];
        end
    else
        llgNote = '';
    end
    if isempty(llgNote)
        ndText = [tNote ';' bNote];
    else
        ndText = [tNote ';' bNote ';' llgNote];
    end

    floc{end+1, 1} = loc; %#ok<AGROW>
    ftyp{end+1, 1} = typ; %#ok<AGROW>
    cids{end+1, 1} = cs; %#ok<AGROW>
    pfunc{end+1, 1} = pf; %#ok<AGROW>
    pavail{end+1, 1} = pa; %#ok<AGROW>
    ptime(end+1, 1) = tp; %#ok<AGROW>
    bfunc{end+1, 1} = bf; %#ok<AGROW>
    btime(end+1, 1) = tb; %#ok<AGROW>
    ctsrc{end+1, 1} = cts; %#ok<AGROW>
    setsrc{end+1, 1} = ssrc; %#ok<AGROW>
    det{end+1, 1} = pa; %#ok<AGROW>
    determ(end+1, 1) = strcmp(pa, 'ASSERTABLE-DETECT'); %#ok<AGROW>
    ndet{end+1, 1} = ndText; %#ok<AGROW>

    % === SIEMENS-BASELINE BACKUP TWIN (F1 generator-zone rows only) ===
    if strcmp(loc, 'F1')
        Pb = phase5b_pickup(blD, ILOAD_GEN, IminArg);
        if ~Pb.use_phase5_time
            tbb = NaN;
            bbNote = ['Siemens-baseline-backup-NaN-DT-??-tdef-3.00s-??-' ...
                'PENDING-COORDINATION-inverse-prohibited-use_phase5_time-' ...
                'false-never-dispatched-to-frozen-operating-time'];
        else
            tbb = NaN;
            bbNote = ['Siemens-baseline-backup-NaN-unexpected-use_phase5_time-' ...
                'true-guarded-NaN-never-tuned'];
        end
        bsrc = ['primary:' psrc ' | backup:' Pb.source];
        floc{end+1, 1} = loc; %#ok<AGROW>
        ftyp{end+1, 1} = typ; %#ok<AGROW>
        cids{end+1, 1} = cs; %#ok<AGROW>
        pfunc{end+1, 1} = pf; %#ok<AGROW>
        pavail{end+1, 1} = pa; %#ok<AGROW>
        ptime(end+1, 1) = tp; %#ok<AGROW>
        bfunc{end+1, 1} = 'GEN-51-SIEMENS-BL'; %#ok<AGROW>
        btime(end+1, 1) = tbb; %#ok<AGROW>
        ctsrc{end+1, 1} = cts; %#ok<AGROW>
        setsrc{end+1, 1} = bsrc; %#ok<AGROW>
        det{end+1, 1} = pa; %#ok<AGROW>
        determ(end+1, 1) = strcmp(pa, 'ASSERTABLE-DETECT'); %#ok<AGROW>
        if isempty(llgNote)
            ndet{end+1, 1} = [tNote ';' bbNote]; %#ok<AGROW>
        else
            ndet{end+1, 1} = [tNote ';' bbNote ';' llgNote]; %#ok<AGROW>
        end
    end
end

E = table(floc, ftyp, cids, pfunc, pavail, ptime, bfunc, btime, ...
    ctsrc, setsrc, det, determ, ndet, 'VariableNames', ...
    {'fault_location', 'fault_type', 'caseID', 'primary_function', ...
    'primary_availability', 'primary_time_s', 'backup_function', ...
    'backup_time_s', 'ct_source', 'setting_source', 'detection', ...
    'determinable', 'not_determinable'});
end

function s = aschar(v)
%ASCHAR  Cell/string scalar to trimmed char.
if isstring(v) && isscalar(v)
    v = char(v);
end
if iscell(v) && isscalar(v)
    v = v{1};
    if isstring(v) && isscalar(v)
        v = char(v);
    end
end
s = strtrim(char(v));
end

function I = bget(B, cs, loc, typ, leg)
%BEGET  Faulted-phase branch magnitude (A) for one B-table leg; NaN if absent.
hit = strcmp(B.caseID, cs) & strcmp(B.location, loc) ...
    & strcmp(B.fault_type, typ) & strcmp(B.leg, leg);
if sum(hit) == 1
    I = double(B.Ibranch_faulted_A(hit));
else
    I = NaN;
end
end

function d = reqdev(devices, id)
%REQDEV  Registry row by device_id or phase5b-prefixed error.
d = findDevice(devices, id);
if isempty(d)
    error('phase5b_effectiveness:devices', 'devices missing required registry row %s.', id);
end
end

function d = findDevice(devices, id)
%FINDDEVICE  First registry row matching device_id (empty if absent).
d = [];
for k = 1:numel(devices)
    v = devices(k).device_id;
    if isstring(v) && isscalar(v)
        v = char(v);
    end
    if ischar(v) && strcmp(strtrim(v), id)
        d = devices(k);
        return;
    end
end
end

function d = devrow(devices, id)
%DEVROW  Alias for the sourced-reference lookup (same honest error path).
d = reqdev(devices, id);
end

function D = phase5b_duty(Tthrough, ratings52G)
%PHASE5B_DUTY  Breaker-duty correction: 52G rows + equipment/interrupting column split (Phase-5b Task C9).
%   D = PHASE5B_DUTY(Tthrough) or D = PHASE5B_DUTY(Tthrough, ratings52G)
%   builds the corrected breaker-duty table. The frozen v1 engine
%   PHASE5_DUTY (matlab/phase5/phase5_duty.m, NEVER modified) is called
%   read-only with EMPTY ratings for the Q0 block: Q0 (52-1 plant outlet
%   breaker at 230-kV GIS) interrupting rating stays NOT DETERMINABLE with
%   rating_kA NaN, exactly as in v1. The v1 engine's Q0-only guard rejects
%   non-Q0 breaker_refs, so the 52G block is computed HERE (per-breaker
%   wrapper, same verdict doctrine as v1) and the NOTE row is carried over
%   from the frozen engine.
%
%   52G duty inputs (locked): GEN_Q branch per (case,loc,type) - column
%   leg_GEN_kA from the phase5_import backbone join - versus the 100 kA sym
%   breaking rating of GCB-10BAC10 (SOURCE-BACKED ledger entry
%   GCB-10BAC10-100kA, REV3_PROGRESS.md:623). The bus/fault-point total is
%   never a duty basis (branch-current doctrine). Missing/NaN GEN_Q leg ->
%   I_sym NaN + MISSING-leg NOT DETERMINABLE (per-circuit contributions
%   never substituted). Rating MISSING (no ratings52G input, no 52G row,
%   NaN/non-positive rating, or empty source) -> rating NaN + MISSING basis
%   + verdict NOT DETERMINABLE (never PASS/FAIL invented). Documented
%   rating -> PASS iff I_sym <= rating else honest FAIL (never tuned).
%   Peak I_peak_kA is borrowed-shape informational only (never duty input).
%
%   Column split (locked, spec S9): breaker_interrupting_rating lives in
%   rating_kA (52G 100 kA; Q0 NaN - the GIS 50 kA short-time withstand from
%   master S17 is EQUIPMENT WITHSTAND, never an interrupting rating, so it
%   MUST NOT appear in rating_kA/basis/verdict/note of any Q0 duty row).
%   equipment_short_circuit_rating lives in the two new columns:
%     Q0 duty rows: equipment_rating_kA 50 + equipment_basis stating it is
%       EQUIPMENT WITHSTAND, SOURCE-BACKED master S17, never interrupting.
%     52G rows: equipment_rating_kA NaN + MISSING equipment_basis (no 52G
%       equipment-withstand sourced anywhere).
%     NOTE row: equipment_rating_kA 50 + equipment_basis on the equipment
%       side; the note text itself carries the split fields
%       I_fault_system_reference (system fault level, never a duty basis)
%       vs equipment_short_circuit_rating (withstand reference, never
%       PASS/FAIL) - system-vs-equipment wording per spec S9/S12. Verdict
%       NOTE (never PASS/FAIL).
%
%   D cols (locked, 12): location, breaker_ref, fault_type, caseID,
%     I_sym_kA, I_peak_kA, rating_kA, basis, verdict, note,
%     equipment_rating_kA, equipment_basis.
%   Row order: n Q0 duty rows (input order), n 52G duty rows (input order),
%   exactly one NOTE row. Verdict domain: PASS / FAIL /
%   NOT DETERMINABLE FROM AVAILABLE DATA / NOTE.
%   ratings52G form: [] (MISSING) or struct/table with fields/columns
%   breaker_ref, rating_kA, source; only breaker_ref '52G' is accepted -
%   a Q0 entry errors (the 50 kA withstand must never become an
%   interrupting rating) as do Q1/Q2/Q9/Q51/Q52/Q8 (disconnectors/earthing
%   never duty). Default when omitted: 100 kA SOURCE-BACKED ledger entry.
%   All errors raised HERE are 'phase5b_duty'-prefixed (the frozen engine
%   keeps its own 'phase5_duty' IDs when it errors internally).
if nargin < 1
    error('phase5b_duty:args', 'usage: D = phase5b_duty(Tthrough, ratings52G).');
end
if nargin < 2
    ratings52G = struct('breaker_ref', '52G', 'rating_kA', 100.0, ...
        'source', 'SOURCE-BACKED:ledger-GCB-10BAC10-100kA-REV3_PROGRESS.md:623');
end
if ~istable(Tthrough) || height(Tthrough) < 1
    error('phase5b_duty:args', 'Tthrough must be a non-empty table (phase5_import output).');
end
for k = 1:numel({'fault_location', 'fault_type', 'caseID', 'leg_GEN_kA'})
    need = {'fault_location', 'fault_type', 'caseID', 'leg_GEN_kA'};
    if ~any(strcmp(Tthrough.Properties.VariableNames, need{k}))
        error('phase5b_duty:schema', 'Tthrough missing required column %s (GEN_Q branch required for 52G).', need{k});
    end
end
[has52, rating52, ratingSrc] = parse52(ratings52G);
% Q0 block from the FROZEN v1 engine (read-only; always MISSING ratings so
% Q0 interrupting stays NOT DETERMINABLE with rating NaN, as in v1).
DQ0 = phase5_duty(Tthrough, []);
isNoteQ = strcmp(DQ0.verdict, 'NOTE');
Qduty = DQ0(~isNoteQ, :);
Nrow = DQ0(isNoteQ, :);
if height(Nrow) ~= 1
    error('phase5b_duty:engine', 'frozen engine must return exactly one NOTE row (got %d).', height(Nrow));
end
n = height(Qduty);
locs = tocelld(Tthrough.fault_location);
typs = tocelld(Tthrough.fault_type);
cases = tocelld(Tthrough.caseID);
legGEN = double(Tthrough.leg_GEN_kA(:));
legTOT = legopt(Tthrough, 'leg_LINE_total_kA', height(Tthrough));
peak = legopt(Tthrough, 'r_kappa_ip', height(Tthrough));
peakA = legopt(Tthrough, 'I_peak_kA', height(Tthrough));
hasPeakCol = any(strcmp(Tthrough.Properties.VariableNames, 'r_kappa_ip')) || ...
    any(strcmp(Tthrough.Properties.VariableNames, 'I_peak_kA'));
% 52G block: GEN_Q branch vs 100 kA (v1 verdict doctrine, per-breaker).
oLoc = cell(n, 1); oTyp = cell(n, 1); oCase = cell(n, 1);
oSym = NaN(n, 1); oPk = NaN(n, 1); oRate = NaN(n, 1);
oBasis = cell(n, 1); oVd = cell(n, 1); oNote = cell(n, 1);
oEq = NaN(n, 1); oEqB = cell(n, 1);
for i = 1:n
    sym = legGEN(i);
    pkv = NaN;
    if isfinite(peak(i)), pkv = peak(i);
    elseif isfinite(peakA(i)), pkv = peakA(i);
    end
    oLoc{i} = locs{i}; oTyp{i} = typs{i}; oCase{i} = cases{i};
    oSym(i) = sym; oPk(i) = pkv;
    if isfinite(sym) && has52
        oRate(i) = rating52;
        if sym <= rating52
            vd = 'PASS';
            vnote = sprintf('PASS: GEN_Q through-current %.4g kA <= documented 52G rating %.4g kA', sym, rating52);
        else
            vd = 'FAIL';
            vnote = sprintf(['FAIL: GEN_Q through-current %.4g kA > documented 52G rating %.4g kA; ' ...
                'honest-shortfall-never-tuned'], sym, rating52);
        end
        basis = sprintf(['SOURCE-BACKED:Phase-4-production-import through-current branch leg_GEN_kA ' ...
            '(GEN_Q generator-breaker path toward fault for %s %s %s); ' ...
            'breaker_interrupting_rating %.4g kA sym breaking GCB-10BAC10 source %s'], ...
            locs{i}, typs{i}, cases{i}, rating52, ratingSrc);
        note = sprintf(['branch leg_GEN_kA %.4g kA (GEN_Q generator-breaker path); ' ...
            'bus-total %.4g rejected (bus total, never duty); ' ...
            'peak %.4g kA borrowed-shape design-defined informational only (never duty input)'], ...
            sym, legTOT(i), pkv);
    else
        if ~isfinite(sym)
            vd = 'NOT DETERMINABLE FROM AVAILABLE DATA';
            basis = sprintf(['SOURCE-BACKED:Phase-4-production-import through-current branch leg_GEN_kA ' ...
                '(GEN_Q generator-breaker path for %s %s %s); ' ...
                'MISSING:through-current-leg (leg_GEN_kA NaN; per-circuit contributions never substituted); ' ...
                'rating %s'], locs{i}, typs{i}, cases{i}, rating_state(has52, rating52, ratingSrc));
            note = sprintf(['MISSING-leg: branch leg_GEN_kA unavailable for %s %s %s (bus total never substituted); ' ...
                'peak %.4g kA borrowed-shape design-defined informational only (never duty input)'], ...
                locs{i}, typs{i}, cases{i}, pkv);
        else
            vd = 'NOT DETERMINABLE FROM AVAILABLE DATA';
            basis = sprintf(['SOURCE-BACKED:Phase-4-production-import through-current branch leg_GEN_kA ' ...
                '(GEN_Q generator-breaker path toward fault for %s %s %s); ' ...
                'MISSING:52G-interrupting-rating (no source proves a 52G rating; never invented)'], ...
                locs{i}, typs{i}, cases{i});
            note = sprintf(['branch leg_GEN_kA %.4g kA (GEN_Q generator-breaker path); ' ...
                'bus-total %.4g rejected (bus total, never duty); ' ...
                'peak %.4g kA borrowed-shape design-defined informational only (never duty input)'], ...
                sym, legTOT(i), pkv);
        end
    end
    if ~isfinite(pkv) && ~hasPeakCol
        note = [note ';MISSING-peak-informational-only (never duty input)'];
    elseif ~isfinite(pkv)
        note = [note ';MISSING-peak (row peak unavailable, never duty input)'];
    end
    oVd{i} = vd; oBasis{i} = basis; oNote{i} = note;
    if has52
        oEqB{i} = sprintf(['MISSING:no-52G-equipment-withstand-sourced (never invented); ' ...
            'breaker_interrupting_rating %.4g kA sym breaking is interrupting, never an equipment rating'], rating52);
    else
        oEqB{i} = ['MISSING:no-52G-equipment-withstand-sourced (never invented); ' ...
            '52G interrupting rating itself MISSING (never invented)'];
    end
end
G52 = table(oLoc, repmat({'52G'}, n, 1), oTyp, oCase, oSym, oPk, oRate, ...
    oBasis, oVd, oNote, oEq, oEqB, 'VariableNames', ...
    {'location', 'breaker_ref', 'fault_type', 'caseID', 'I_sym_kA', ...
    'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
    'equipment_rating_kA', 'equipment_basis'});
% Q0 equipment columns: GIS 50 kA short-time withstand (equipment, never interrupting).
Qeq = 50.0 * ones(n, 1);
QeqB = cell(n, 1);
for i = 1:n
    QeqB{i} = ['SOURCE-BACKED:master-S17-GIS-short-time-withstand-50kA (EQUIPMENT WITHSTAND, never interrupting); ' ...
        'equipment_short_circuit_rating 50 kA (withstand, never a breaker_interrupting_rating); ' ...
        'Q0 interrupting rating NOT DETERMINABLE (never invented)'];
end
Qduty.equipment_rating_kA = Qeq;
Qduty.equipment_basis = QeqB;
% NOTE row carried over from the frozen engine + equipment side of the split.
% System-vs-equipment wording (spec S9/S12): the note text carries the
% separate fields I_fault_system_reference vs equipment_short_circuit_rating.
Nrow.equipment_rating_kA = 50.0;
Nrow.equipment_basis = {['SOURCE-BACKED:master-S17-GIS-short-time-withstand-50kA (EQUIPMENT WITHSTAND, never interrupting); ' ...
    'equipment_short_circuit_rating 50 kA (withstand reference for the NOTE comparison, never an interrupting rating, never PASS/FAIL)']};
Nrow.note = {[Nrow.note{1} '; I_fault_system_reference ' sprintf('%.4g', Nrow.I_sym_kA) ...
    ' kA (system fault level for reference only, never a through-current duty basis) vs ' ...
    'equipment_short_circuit_rating 50 kA (GIS short-time withstand, equipment reference, never interrupting, never PASS/FAIL)']};
D = [Qduty; G52; Nrow];
D = D(:, {'location', 'breaker_ref', 'fault_type', 'caseID', 'I_sym_kA', ...
    'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
    'equipment_rating_kA', 'equipment_basis'});
end

function [has52, rating52, ratingSrc] = parse52(ratings)
%PARSE52  Documented 52G interrupting rating needs finite rating > 0 + non-empty source.
% Only breaker_ref '52G' accepted: Q0 errors (50 kA withstand must never
% become an interrupting rating); Q1/Q2/Q9/Q51/Q52/Q8 error (never duty);
% anything else unknown.
has52 = false; rating52 = NaN; ratingSrc = '';
if isempty(ratings)
    return;
end
if istable(ratings)
    vn = ratings.Properties.VariableNames;
    if ~all(ismember({'breaker_ref', 'rating_kA', 'source'}, vn))
        error('phase5b_duty:ratings', 'ratings table needs columns breaker_ref, rating_kA, source.');
    end
    refs = tocelld(ratings.breaker_ref);
    vals = double(ratings.rating_kA);
    srcs = tocelld(ratings.source);
elseif isstruct(ratings)
    if ~all(isfield(ratings, {'breaker_ref', 'rating_kA', 'source'}))
        error('phase5b_duty:ratings', 'ratings struct needs fields breaker_ref, rating_kA, source.');
    end
    refs = cell(numel(ratings), 1); vals = NaN(numel(ratings), 1); srcs = cell(numel(ratings), 1);
    for k = 1:numel(ratings)
        refs{k} = char(ratings(k).breaker_ref);
        vals(k) = double(ratings(k).rating_kA);
        srcs{k} = char(ratings(k).source);
    end
else
    error('phase5b_duty:ratings', 'ratings must be [] or a struct/table with breaker_ref, rating_kA, source.');
end
for k = 1:numel(refs)
    r = strtrim(refs{k});
    if strcmp(r, 'Q0')
        error('phase5b_duty:rating', ['breaker_ref Q0 rejected: the GIS 50 kA value is ' ...
            'EQUIPMENT WITHSTAND (master S17), never a breaker_interrupting_rating; ' ...
            'Q0 interrupting stays NOT DETERMINABLE.']);
    end
    if any(strcmp(r, {'Q1', 'Q2', 'Q9', 'Q51', 'Q52', 'Q8'}))
        error('phase5b_duty:rating', ['breaker_ref %s is a disconnector/earthing device, ' ...
            'never duty (only Q0 52-1 and 52G are duty-eligible).'], r);
    end
    if ~strcmp(r, '52G')
        error('phase5b_duty:rating', 'unknown breaker_ref %s (need 52G).', r);
    end
end
hit = find(strcmp(strtrim(refs), '52G'), 1, 'first');
if isempty(hit)
    return;
end
if isfinite(vals(hit)) && vals(hit) > 0 && ~isempty(strtrim(srcs{hit}))
    has52 = true; rating52 = vals(hit); ratingSrc = strtrim(srcs{hit});
end
end

function s = rating_state(has52, rating52, ratingSrc)
%RATING_STATE  Short rating-provenance tag for MISSING-leg basis strings.
if has52
    s = sprintf('documented 52G %.4g kA (%s)', rating52, ratingSrc);
else
    s = 'MISSING (no source proves a 52G rating; never invented)';
end
end

function v = legopt(Tsec, name, n)
%LEGOPT  Optional leg column (kA) or NaN vector when absent.
if any(strcmp(Tsec.Properties.VariableNames, name))
    v = double(Tsec.(name)(:));
    if numel(v) ~= n, v = NaN(n, 1); end
    v(~isfinite(v)) = NaN;
else
    v = NaN(n, 1);
end
end

function c = tocelld(v)
%TOCELLD  Normalize table text column (cellstr/string/char) to cellstr.
if iscell(v)
    c = v(:);
    for k = 1:numel(c)
        if isstring(c{k}) && isscalar(c{k}), c{k} = char(c{k}); end
    end
elseif isstring(v)
    c = cellstr(v(:));
elseif ischar(v)
    c = cellstr(v);
else
    error('phase5b_duty:schema', 'text column must be cell/string/char.');
end
end

function V = phase5b_validate(varargin)
%PHASE5B_VALIDATE  v2 validation legs B01-B13 + R0 re-import identity (Phase-5b Task C12).
%   V = PHASE5B_VALIDATE() returns struct V with field .legs, a struct array
%   with fields id (char), pass (logical), residual (double), note (char).
%   14 legs: R0 Phase-4 regression + B01..B13 (Ashuganj South, MATLAB).
%
%   Legs (each: pass bool + residual + note; every leg must pass for the gate):
%     R0  Phase-4 regression via phase5_import: F3 LLL OUT == 50.5308851865359
%         kA within 1e-6, F1 LG OUT == 0.00727200442799167 kA within 1e-9
%         (same tolerances as v1 R0).
%     B01 CT mapping (1600/1 GSUT/GIS SOURCE-BACKED, core NOT-DETERMINABLE
%         where bay-dependent, 16k-scope gen-only, zero 2000/16000, GEN
%         15000/1 unchanged, TMS 0.20 study rows).
%     B02 Siemens baseline (17171 A / 1.1447 A-sec / DT-?? / tdef 3.00 s ??
%         / inverse-prohibited via use_phase5_time false + frozen-library
%         refusal of DT-??).
%     B03 Variant separation (STUDY GEN-51 distinct from PHYSICAL baseline;
%         alias GEN-51-SI; SI/TMS-0.20/inverse-allowed; convergence <0.5%
%         with characteristic split; DISABLED high-set + note errors).
%     B04 Branch-not-total (43758 absent from DETECTION logic). Scan targets
%         detection modules (mindetect/effectiveness/pickup) only -- NOT plot
%         labels: 43758.86 legitimately appears as Imin REFERENCE arg in
%         phase5b_tcc (IMIN_PHASE_A into phase5b_pickup shape arg + study
%         time anchor per C10 review) and is excluded by design. Functional
%         branch-only proof: mindetect identical with totals columns removed.
%     B05 52G presence + 100 kA (GEN-52G PHYSICAL SOURCE-BACKED 10BAC10 with
%         12.4 kA cont / 100 kA breaking; topology breaker_52G 10BAC10 +
%         rating_100kA 100; duty 52G F1 LLL OUT 55.0487 kA PASS vs 100 kA).
%     B06 Zone mapping + F-mapping (G/T/B/L; exactly one primary per fault:
%         F1->87G, F2->87T, F3->87B, F4->7SD; every zone device in registry;
%         trip/lockout/BF fields all NOT-DETERMINABLE).
%     B07 F3->87B detect-vs-time split (NOT-DETERMINABLE + NaN time with
%         no-sourced-7SS523-pickup + magnitude-observation reason; study
%         backup GIS-Q0-51 finite and equal to frozen phase5_time on the
%         LINE_total through-convention current).
%     B08 F4->7SD (NOT-DETERMINABLE + NaN time with no-sourced-7SD5221
%         reason + LINE_B1 trace; all F4 study rows NOT-DETERMINABLE with
%         NaN primary times and finite B1-outfeed backups -- never the
%         LINE_total cancellation residual).
%     B09 51N/59N/64G split (GEN-51N-SI-STUDY 5 A SENSITIVITY TMS 0.15;
%         59N/64G/64R PHYSICAL NaN + 381.05 VT datum; 64G never a 3I0 pickup)
%         + F2-LG-backup consistency probe from C8 concern (F2 LG backup is
%         GSUT-HV-51 phase, never GEN-51N; finite time).
%     B10 Rating split (equipment~=interrupting: Q0 rating NaN + equipment
%         50 EQUIPMENT WITHSTAND never interrupting; 52G rating 100 +
%         equipment NaN MISSING; rating domain NaN/100/50-only; NOTE never
%         PASS/FAIL with I_fault_system_reference vs
%         equipment_short_circuit_rating split fields).
%     B11 8.414 kA trace (re-asserts C5 key identities live: contributions
%         leg 8.4141 +-1e-4, KCL <1e-9, anchor 9.4757, redistribution +
%         leg/total>100 verdict branch-through-current-magnitude, import join
%         identity; never nests test_phase5b_branch_audit or any runner --
%         re-assertion only, by design).
%     B12 No-conflation (no PHYSICAL row carries STUDY numbers and vice
%         versa -- cross-scan registry + pickup engine: STUDY pickups NaN in
%         registry; PHYSICAL non-sourced pickups NaN; TMS split; DT-?? vs SI
%         characteristic split; provenance split; protection_function tags).
%     B13 R0 identity (same anchors and tolerances as v1 R0, v2 path).
%
%   Single-effectiveness structure: phase5b_effectiveness(T40, devices) is
%   called ONCE here (~minutes via one phase5b_branch_phasors recompute) and
%   the resulting E table is reused across B07/B08/B09 below. B11 re-asserts
%   C5 identities inline and never calls test_phase5b_branch_audit or any
%   test runner (no nested runners by design).
%
%   Infrastructure failures (missing CSV, bad schema) error loudly with
%   phase5b-prefixed identifiers; measured shortfalls yield pass=false with
%   residual + note, never retuned. All errors raised here are
%   'phase5b'-prefixed (reuse of frozen v1 functions keeps 'phase5' IDs).
if nargin ~= 0
    error('phase5b_validate:args', 'usage: V = phase5b_validate().');
end
root = ashuganj_root();
R = phase5b_registry();
Ti = phase5_import(root);
D = phase5b_duty(Ti);
Z = phase5b_zones();
E = phase5b_effectiveness(Ti, R.devices);
ids = {'R0', 'B01', 'B02', 'B03', 'B04', 'B05', 'B06', 'B07', ...
    'B08', 'B09', 'B10', 'B11', 'B12', 'B13'};
legs = repmat(struct('id', '', 'pass', false, 'residual', NaN, 'note', ''), 1, 14);
[p, r, n] = legR0(Ti);        legs(1) = mkleg(ids{1}, p, r, n);
[p, r, n] = legB01(R);        legs(2) = mkleg(ids{2}, p, r, n);
[p, r, n] = legB02(R);        legs(3) = mkleg(ids{3}, p, r, n);
[p, r, n] = legB03(R);        legs(4) = mkleg(ids{4}, p, r, n);
[p, r, n] = legB04(Ti, R);    legs(5) = mkleg(ids{5}, p, r, n);
[p, r, n] = legB05(R, Ti, D); legs(6) = mkleg(ids{6}, p, r, n);
[p, r, n] = legB06(R, Z);     legs(7) = mkleg(ids{7}, p, r, n);
[p, r, n] = legB07(E, Ti);    legs(8) = mkleg(ids{8}, p, r, n);
[p, r, n] = legB08(E);        legs(9) = mkleg(ids{9}, p, r, n);
[p, r, n] = legB09(E, Ti, R); legs(10) = mkleg(ids{10}, p, r, n);
[p, r, n] = legB10(D);        legs(11) = mkleg(ids{11}, p, r, n);
[p, r, n] = legB11(root, Ti); legs(12) = mkleg(ids{12}, p, r, n);
[p, r, n] = legB12(R);        legs(13) = mkleg(ids{13}, p, r, n);
[p, r, n] = legB13(Ti);       legs(14) = mkleg(ids{14}, p, r, n);
V = struct('legs', legs);
end

function L = mkleg(id, pass, residual, note)
L = struct('id', id, 'pass', logical(pass), 'residual', double(residual), 'note', char(note));
end

function [p, r, n] = legR0(Ti)
%LEG R0  Phase-4 regression identity via phase5_import (v1 tolerances).
locs = tocell(Ti.fault_location); typs = tocell(Ti.fault_type); cases = tocell(Ti.caseID);
a = Ti(strcmp(locs, 'F3') & strcmp(typs, 'LLL') & strcmp(cases, 'LF360_GAT_OUT'), :);
g = Ti(strcmp(locs, 'F1') & strcmp(typs, 'LG') & strcmp(cases, 'LF360_GAT_OUT'), :);
if height(a) ~= 1 || height(g) ~= 1
    p = false; r = Inf;
    n = 'R0 missing F3-LLL-OUT or F1-LG-OUT backbone row (infrastructure)';
    return;
end
d1 = abs(a.I_primary_kA - 50.5308851865359);
d2 = abs(g.I_primary_kA - 0.00727200442799167);
p = (d1 < 1e-6) && (d2 < 1e-9);
r = max(d1, d2);
n = sprintf('F3-LLL-OUT %.10f kA (d %.2g, tol 1e-6); F1-LG-OUT %.14f kA (d %.2g, tol 1e-9)', ...
    a.I_primary_kA, d1, g.I_primary_kA, d2);
end

function [p, r, n] = legB01(R)
%LEG B01  CT mapping: 1600/1 GSUT/GIS SOURCE-BACKED, core NOT-DET, 16k gen-only.
viol = 0;
msgs = {};
ids = {R.devices.device_id};
g = R.devices(strcmp(ids, 'GSUT-HV-51'));
q = R.devices(strcmp(ids, 'GIS-Q0-51'));
p51 = R.devices(strcmp(ids, 'GEN-51'));
p51n = R.devices(strcmp(ids, 'GEN-51N'));
if ~(isscalar(g) && g.ct_ratio == 1600 && strcmp(g.ct_source, 'SOURCE-BACKED')), viol = viol + 1; msgs{end+1} = 'GSUT-1600-SOURCE-BACKED'; end
if ~(isscalar(q) && q.ct_ratio == 1600 && strcmp(q.ct_source, 'SOURCE-BACKED')), viol = viol + 1; msgs{end+1} = 'GIS-1600-SOURCE-BACKED'; end
if ~(isscalar(g) && g.physical_CT_ratio == 1600 && g.study_CT_ratio == 1600), viol = viol + 1; msgs{end+1} = 'GSUT-phys/study-1600'; end
if ~(isscalar(q) && q.physical_CT_ratio == 1600 && q.study_CT_ratio == 1600), viol = viol + 1; msgs{end+1} = 'GIS-phys/study-1600'; end
if ~(isscalar(g) && ischar(g.selected_CT_core) && ~isempty(strfind(g.selected_CT_core, 'NOT-DETERMINABLE'))), viol = viol + 1; msgs{end+1} = 'GSUT-core-NOT-DET'; end
if ~(isscalar(q) && ischar(q.selected_CT_core) && ~isempty(strfind(q.selected_CT_core, 'NOT-DETERMINABLE'))), viol = viol + 1; msgs{end+1} = 'GIS-core-NOT-DET'; end
if ~(isscalar(p51) && p51.ct_ratio == 15000 && strcmp(p51.ct_source, 'SOURCE-BACKED')), viol = viol + 1; msgs{end+1} = 'GEN-15000-kept'; end
if ~(isscalar(p51n) && p51n.ct_ratio == 15000 && strcmp(p51n.ct_source, 'SOURCE-BACKED')), viol = viol + 1; msgs{end+1} = 'GEN-51N-15000-kept'; end
ratios = [R.devices.ct_ratio];
if any(ratios == 2000), viol = viol + 1; msgs{end+1} = 'no-2000'; end
if any(ratios == 16000), viol = viol + 1; msgs{end+1} = 'no-16000'; end
if any([R.devices.physical_CT_ratio] == 2000 | [R.devices.study_CT_ratio] == 2000), viol = viol + 1; msgs{end+1} = 'no-phys/study-2000'; end
if any([R.devices.physical_CT_ratio] == 16000 | [R.devices.study_CT_ratio] == 16000), viol = viol + 1; msgs{end+1} = 'no-phys/study-16000'; end
capable = {'GEN-51', 'GEN-51N', 'GSUT-HV-51', 'GIS-Q0-51', 'GIS-Q0-50'};
for k = 1:numel(capable)
    d = R.devices(strcmp(ids, capable{k}));
    if ~(isscalar(d) && strcmp(d.layer, 'STUDY') && d.tms == 0.20), viol = viol + 1; msgs{end+1} = ['TMS-0.20-' capable{k}]; end
end
try
    sGen = phase5b_ct_scope('GEN-51');
    sGenN = phase5b_ct_scope('GEN-51N');
    sGsut = phase5b_ct_scope('GSUT-HV-51');
    sGis = phase5b_ct_scope('GIS-Q0-51');
    sGis50 = phase5b_ct_scope('GIS-Q0-50');
    wGen = phase5b_sensitivity_scope('GEN-51');
    wGis = phase5b_sensitivity_scope('GIS-Q0-51');
    if ~(sGen == true && sGenN == true && sGsut == false && sGis == false && sGis50 == false && wGen == true && wGis == false)
        viol = viol + 1; msgs{end+1} = '16k-scope-gen-only';
    end
catch
    viol = viol + 1; msgs{end+1} = 'scope-helper-error';
end
if ~(isfield(R.gen, 'Imax_A') && R.gen.Imax_A == 14309), viol = viol + 1; msgs{end+1} = 'Imax-14309'; end
p = (viol == 0);
r = double(viol);
if p
    n = 'GSUT/GIS 1600/1 SOURCE-BACKED + phys/study 1600; cores NOT-DETERMINABLE bay-dependent; GEN 15000/1 kept; zero 2000/16000; study TMS 0.20; 16k-scope gen-only';
else
    n = ['B01 shortfalls: ' strjoin(msgs, ',')];
end
end

function [p, r, n] = legB02(R)
%LEG B02  Siemens DT baseline: 17171/1.1447/DT-??/tdef-3.00-??/inverse-prohibited.
ids = {R.devices.device_id};
bl = R.devices(strcmp(ids, 'GEN-51-SIEMENS-BL'));
ok = isscalar(bl) && strcmp(bl.layer, 'PHYSICAL') && strcmp(bl.ansi, '50/51-DT') ...
    && strncmp(bl.provenance, 'USER_ASSERTED_PENDING_DOC', 25) ...
    && bl.ct_ratio == 15000 && strcmp(bl.ct_source, 'SOURCE-BACKED') ...
    && abs(bl.pickup_A - 17171) / 17171 < 1e-12 && strcmp(bl.curve, 'DT-??');
FL_GENQ_A = 9.47574312698307 * 1000;
IMIN_PHASE_A = 43758.8597559;
P = phase5b_pickup(bl, FL_GENQ_A, IMIN_PHASE_A);
e1 = abs(P.setting - 17171) / 17171;
e2 = abs(P.setting_sec_A - 1.1447) / 1.1447;
e3 = abs(P.setting_sec_A - P.setting / 15000) / P.setting_sec_A;
e4 = abs(P.tdef - 3.00);
cTime = strcmp(P.time_status, 'NOT-DETERMINABLE-??-PENDING-COORDINATION');
cCurve = strcmp(P.curve, 'DT-??');
cFlag = islogical(P.use_phase5_time) && isscalar(P.use_phase5_time) && ~P.use_phase5_time;
cSrc = ~isempty(strfind(P.source, 'USER_ASSERTED_PENDING_DOC'));
try
    phase5_time(2 * P.setting_sec_A, P.setting_sec_A, P.tdef, P.curve);
    refusedT = false;
catch ME
    refusedT = strncmp(ME.identifier, 'phase5', 6);
end
try
    phase5_curve(2.0, P.curve, 0.20);
    refusedC = false;
catch ME
    refusedC = strncmp(ME.identifier, 'phase5', 6);
end
xerr = abs(1.2 * 14309 - 17171) / 17171;
p = ok && (e1 < 0.005) && (e2 < 0.005) && (e3 < 1e-12) && (e4 < 1e-12) ...
    && cTime && cCurve && cFlag && cSrc && refusedT && refusedC && (xerr < 0.005);
r = max([e1, e2, e3, e4, xerr]);
n = sprintf(['baseline 17171 A (rel %.2g, tol 0.5%%) / 1.1447 A-sec (rel %.2g) / DT-?? / tdef 3.00 s ?? ' ...
    'NOT-DETERMINABLE / inverse-prohibited use_phase5_time false (frozen refusal ok); ' ...
    'registry mirror ok; cross-check 1.2x14309 rel %.2g'], e1, e2, xerr);
end

function [p, r, n] = legB03(R)
%LEG B03  Variant separation: STUDY GEN-51 vs PHYSICAL baseline.
ids = {R.devices.device_id};
g = R.devices(strcmp(ids, 'GEN-51'));
bl = R.devices(strcmp(ids, 'GEN-51-SIEMENS-BL'));
FL_GENQ_A = 9.47574312698307 * 1000;
IMIN_PHASE_A = 43758.8597559;
cLayer = isscalar(g) && strcmp(g.layer, 'STUDY') && isscalar(bl) && strcmp(bl.layer, 'PHYSICAL');
cDistinct = ~strcmp(g.device_id, bl.device_id);
cAlias = strcmp(phase5b_id_aliases('GEN-51-SI'), 'GEN-51') ...
    && strcmp(phase5b_id_aliases('GEN-51'), 'GEN-51') ...
    && strcmp(phase5b_id_aliases('GEN-51-SIEMENS-BL'), 'GEN-51-SIEMENS-BL');
Pg = phase5b_pickup(g, FL_GENQ_A, IMIN_PHASE_A);
ga = g; ga.device_id = 'GEN-51-SI';
Pa = phase5b_pickup(ga, FL_GENQ_A, IMIN_PHASE_A);
Pb = phase5b_pickup(bl, FL_GENQ_A, IMIN_PHASE_A);
eSet = abs(Pg.setting - 17170.8) / 17170.8;
eAlias = abs(Pa.setting - Pg.setting) / Pg.setting;
cStudy = (abs(Pg.tms - 0.20) < 1e-12) && strcmp(Pg.curve, 'SI') ...
