cImp = (height(irow) == 1) && (abs(irow.leg_GEN_kA - leg) < 1e-9);
p = cLeg && cKCL && cAnchor && cJoin && cEv && cImp;
r = abs(leg - 8.4141);
if p
    verdict = 'branch-through-current-magnitude';
else
