end
n = sprintf(['F1-LG-OUT leg_GEN %.6f kA (d %.2g vs 8.4141, tol 1e-4); KCL <1e-9; anchor GEN_Q %.4f kA; ' ...
    'rel %.4f (>0.05) leg/total %.1f (>100) verdict %s; import join carries same leg'], leg, r, anchor, rel, legover, verdict);
