function c = tocell(v)
%TOCELL  Normalize table text column to cellstr.
if iscell(v)
    c = v(:);
elseif isstring(v)
    c = cellstr(v(:));
elseif ischar(v)
    c = cellstr(v);
else
    error('phase5b_validate:schema', 'text column must be cell/string/char.');
end
end

function tf = tableHas(D, pat)
%TABLEHAS  True if pattern appears in any variable name or string cell.
tf = ~isempty(strfind(strjoin(D.Properties.VariableNames, '|'), pat));
if tf, return; end
for k = 1:numel(D.Properties.VariableNames)
    col = D.(D.Properties.VariableNames{k});
    if iscell(col)
        for i = 1:numel(col)
            vv = col{i};
            if (ischar(vv) || isstring(vv)) && ~isempty(strfind(char(vv), pat))
                tf = true; return;
            end
        end
    elseif ischar(col) || isstring(col)
        if ~isempty(strfind(char(col), pat)), tf = true; return; end
    end
end
end

