%   (same inputs/outputs/behavior - move, don't rewrite). The short task
%   signature S = PHASE5B_SENSITIVITY_V2(T40, devices) maps to this triple:
%   T40 is the joined backbone table, devicesProd the C4-stamped devices
%   copy, Rreg the phase5b_registry struct (ct_legacy fence read here).
%   Primary function name matches this filename per MATLAB requirement
%   (exact name phase5b_sensitivity_v2 avoids clashing with frozen v1
%   phase5_sensitivity, which is never modified).
%   The frozen PHASE5_SENSITIVITY is BLOCKED for v2 reuse (never modified):
%   it hard-codes the v1 2000 CT on its upstream GSUT leg
%   (phase5_sensitivity.m:137 'IsUp = pkUp / 2000', :190 'primUp / 2000',
%   :193 reason 'upstream-GSUT-HV-51-2000/1-untouched', comments :9/:11)
%   instead of reading device ct_ratio (1600 in v2). Evidence pinned in
%   test_phase5b_writer. This engine ports the frozen GEN-scope doctrine
%   exactly, reading every pickup/CT/TMS from the v2-resolved devices:
%     GEN-51 (phase, all 40 combos) + GEN-51N (earth, LG/LLG only, 20 rows)
%     = 60 rows; GEN dial fixed from the PRIMARY scheme via the device CT
%     (Is_fixed = P/ct_device, 15000); legacy secondaries via Rreg.ct_legacy
%     (16000 fence, read never hard-coded); upstream GSUT-HV-51 backup via
%     ITS device CT (1600 - the fix) with the v2-resolved pickup/TMS;
%     EF TMS 0.15 from the stamped devices (pickup-resolved, never registry
%     0.20). Frozen phase5_ct + phase5_time + phase5_ct_table(T40,16000)
%     audit reference only (legacy fence unchanged in v2).
%   Relay primaries mirror frozen branch parity: GEN-51 phase -> GEN_Q leg
%   else net total; GEN-51N F1/F2 -> 3xI0 neutral-once else LG-exact If/3
%   else NaN; GEN-51N F3/F4/F5 -> 3x leg_NER_earth delta block else NaN.
%   Verdict doctrine identical to frozen (CTI 0.3 s; NO-TRIP / NO-PAIR /
%   NOT DETERMINABLE FROM AVAILABLE DATA). 28 locked cols, scope
%   SENSITIVITY, provenance LEGACY-tagged + v2-adaptation note.
%   Purity: inputs in, new table out; no output calls and no shared
%   workspace state. All errors are 'phase5b'-prefixed.
d51 = finddev(devicesProd, 'GEN-51');
d51N = finddev(devicesProd, 'GEN-51N');
dUp = finddev(devicesProd, 'GSUT-HV-51');
ctGen = read_ct(d51, 'GEN-51');
ctLeg = double(Rreg.ct_legacy);
if ~(isscalar(ctLeg) && isfinite(ctLeg) && ctLeg > 0)
    error('phase5b_production:sensitivity', 'Rreg.ct_legacy must be finite > 0 (16000 fence, read never hard-coded).');
end
ctUp = read_ct(dUp, 'GSUT-HV-51');
pk51 = read_pickup(d51, 'GEN-51');
pkN = read_pickup(d51N, 'GEN-51N');
pkUp = read_pickup(dUp, 'GSUT-HV-51');
[tms51, cv51] = read_tc(d51, 'GEN-51');
[tmsN, cvN] = read_tc(d51N, 'GEN-51N');
[tmsUp, cvUp] = read_tc(dUp, 'GSUT-HV-51');
IsFix51 = pk51 / ctGen;
IsFixN = pkN / ctGen;
IsUp = pkUp / ctUp;
CTI = 0.3;
locs = tocell(T40.fault_location);
typs = tocell(T40.fault_type);
cases = tocell(T40.caseID);
n = height(T40);
If_A = double(T40.I_primary_A(:));
If_kA = double(T40.I_primary_kA(:));
if any(~isfinite(If_A)) || any(~isfinite(If_kA))
    error('phase5b_production:sensitivity', 'T40 fault currents must be finite.');
end
hasIseq0 = any(strcmp(T40.Properties.VariableNames, 'Iseq0_kA'));
if hasIseq0
    Iseq0_kA = double(T40.Iseq0_kA(:));
else
    Iseq0_kA = NaN(n, 1);
end
legGEN = legcol(T40, 'leg_GEN_kA', n);
legHV = legcol(T40, 'leg_GSUT_HV_kA', n);
legNER = legcol(T40, 'leg_NER_earth_kA', n);
Tleg = phase5_ct_table(T40, 16000, 'LEGACY-16000/1');
if height(Tleg) ~= n
    error('phase5b_production:sensitivity', 'legacy audit table row count diverged from T40.');
end
earthMask = strcmp(typs, 'LG') | strcmp(typs, 'LLG');
nEarth = sum(earthMask);
total = n + nEarth;
oLoc = cell(total, 1); oTyp = cell(total, 1); oCase = cell(total, 1);
oDev = cell(total, 1); oPath = cell(total, 1);
oIprim = NaN(total, 1); oIk = NaN(total, 1);
oIsecP = NaN(total, 1); oIsecS = NaN(total, 1);
oCtP = repmat(ctGen, total, 1); oCtL = repmat(ctLeg, total, 1);
oTag = repmat({'LEGACY-16000/1'}, total, 1);
oPk = NaN(total, 1); oTms = NaN(total, 1); oCv = cell(total, 1);
oTp = NaN(total, 1); oTs = NaN(total, 1); oDt = NaN(total, 1);
oDir = cell(total, 1);
oMgP = NaN(total, 1); oMgS = NaN(total, 1); oDmg = NaN(total, 1);
oMdir = cell(total, 1);
oVp = cell(total, 1); oVs = cell(total, 1);
oScope = repmat({'SENSITIVITY'}, total, 1);
oProv = repmat({['LEGACY:CT-16000/1-fenced-sensitivity-vs-PRIMARY-15000/1-GEN-v2-adapted-' ...
    'upstream-1600/1-device-CT-SOURCE-BACKED-Phase-4-import']}, total, 1);
oReason = cell(total, 1);
j = 0;
for i = 1:n
    loc = locs{i};
    typ = typs{i};
    cs = cases{i};
    isGenZone = strcmp(loc, 'F1') || strcmp(loc, 'F2');
    if isfinite(legGEN(i)) && legGEN(i) >= 0
        prim51 = legGEN(i) * 1000;
        path51 = 'GEN_Q-branch-leg_GEN_kA-SOURCE-BACKED';
    else
        prim51 = If_A(i);
        path51 = 'net-total-fallback-no-leg-join';
    end
    secP51 = phase5_ct(prim51, ctGen).Isec_A;
    secS51 = phase5_ct(prim51, ctLeg).Isec_A;
    tP51 = sidetime(secP51, IsFix51, tms51, cv51);
    tS51 = sidetime(secS51, IsFix51, tms51, cv51);
    if isGenZone
        if isfinite(legHV(i)) && legHV(i) >= 0
            primUp = legHV(i) * 1000;
            upTag = 'GSUT_HV-branch-leg_GSUT_HV_kA-SOURCE-BACKED';
        else
            primUp = If_A(i);
            upTag = 'net-total-fallback-no-leg-join';
        end
        tUp = sidetime(primUp / ctUp, IsUp, tmsUp, cvUp);
        [mgP, vP] = pairverdict(tP51, tUp, CTI);
        [mgS, vS] = pairverdict(tS51, tUp, CTI);
        mgNote = sprintf([';upstream-GSUT-HV-51-v2-device-CT-%.0f/1(t_up=%.3fs;%s);' ...
            'CTI-0.3s-study-threshold'], ctUp, tUp, upTag);
    else
        tUp = NaN;
        [mgP, vP] = nopairverdict(tP51);
        [mgS, vS] = nopairverdict(tS51);
        mgNote = [';NO-PAIR (topology): GEN backup not in grid-zone chain;' ...
            'backup-t_down-reported-no-margin-asserted'];
    end
    [dt51, dir51] = classdir(tP51, tS51);
    [dmg51, mdir51] = classmargin(mgP, mgS);
    j = j + 1;
    oLoc{j} = loc; oTyp{j} = typ; oCase{j} = cs; oDev{j} = 'GEN-51';
    oPath{j} = path51; oIprim(j) = prim51; oIk(j) = prim51 / 1000;
    oIsecP(j) = secP51; oIsecS(j) = secS51;
    oPk(j) = pk51; oTms(j) = tms51; oCv{j} = cv51;
    oTp(j) = tP51; oTs(j) = tS51; oDt(j) = dt51; oDir{j} = dir51;
    oMgP(j) = mgP; oMgS(j) = mgS; oDmg(j) = dmg51; oMdir{j} = mdir51;
    oVp{j} = vP; oVs{j} = vS;
    oReason{j} = sprintf(['GEN-51 %s %s %s: relay-primary %.6g A (%s);' ...
        'pickup %.2f A-primary dial-fixed %.6g A-sec via device CT %.0f/1;' ...
        'TMS %.3g %s;t_prim %.3fs t_sens %.3fs dt %.3fs (%s)%s;' ...
        'LEGACY-16000/1 fenced vs PRIMARY-15000/1 GEN (v2-adapted upstream %.0f/1)'], ...
        loc, typ, cs, prim51, path51, pk51, IsFix51, ctGen, ...
        tms51, cv51, tP51, tS51, dt51, dir51, mgNote, ctUp);
    if strcmp(typ, 'LG') || strcmp(typ, 'LLG')
        if isGenZone
            if isfinite(Iseq0_kA(i))
                primN = 3 * Iseq0_kA(i) * 1000;
                pathN = '3I0-fault-total-Iseq0-SOURCE-BACKED-neutral-counted-once';
                missN = false;
            elseif strcmp(typ, 'LG')
                primN = If_A(i);
                pathN = '3I0-LG-exact-If-over-3-DERIVED-neutral-counted-once';
                missN = false;
            else
                primN = NaN;
                pathN = 'MISSING-no-Iseq0-LLG-neutral-counted-once-N/A';
                missN = true;
            end
        else
            if isfinite(legNER(i)) && legNER(i) >= 0
                primN = 3 * legNER(i) * 1000;
                pathN = '3xleg_NER_earth-delta-block-neutral-counted-once';
                missN = false;
            else
                primN = NaN;
                pathN = '3xleg_NER_earth-MISSING-neutral-counted-once-N/A';
                missN = true;
            end
        end
        if isfinite(primN) && primN >= 0
            secPN = phase5_ct(primN, ctGen).Isec_A;
            secSN = phase5_ct(primN, ctLeg).Isec_A;
            tPN = sidetime(secPN, IsFixN, tmsN, cvN);
            tSN = sidetime(secSN, IsFixN, tmsN, cvN);
        else
            secPN = NaN;
            secSN = NaN;
            tPN = NaN;
            tSN = NaN;
        end
        [vPN, vSN, eNote] = earthverdicts(tPN, tSN, missN, isGenZone, loc, typ, cs);
        [dtN, dirN] = classdir(tPN, tSN);
        j = j + 1;
        oLoc{j} = loc; oTyp{j} = typ; oCase{j} = cs; oDev{j} = 'GEN-51N';
        oPath{j} = pathN; oIprim(j) = primN; oIk(j) = primN / 1000;
        oIsecP(j) = secPN; oIsecS(j) = secSN;
        oPk(j) = pkN; oTms(j) = tmsN; oCv{j} = cvN;
        oTp(j) = tPN; oTs(j) = tSN; oDt(j) = dtN; oDir{j} = dirN;
        oMgP(j) = NaN; oMgS(j) = NaN; oDmg(j) = NaN; oMdir{j} = 'N/A';
        oVp{j} = vPN; oVs{j} = vSN;
        oReason{j} = sprintf(['GEN-51N %s %s %s: relay-primary %.6g A (%s);' ...
            'pickup %.2f A-primary dial-fixed %.6g A-sec via device CT %.0f/1;' ...
            'TMS %.3g %s (EF pickup-resolved);t_prim %.3fs t_sens %.3fs dt %.3fs (%s);%s;' ...
            'LEGACY-16000/1 fenced vs PRIMARY-15000/1 GEN'], ...
            loc, typ, cs, primN, pathN, pkN, IsFixN, ctGen, ...
            tmsN, cvN, tPN, tSN, dtN, dirN, eNote);
    end
end
S = table(oLoc, oTyp, oCase, oDev, oIprim, oIk, oPath, oIsecP, oIsecS, ...
    oCtP, oCtL, oTag, oPk, oTms, oCv, oTp, oTs, oDt, oDir, ...
    oMgP, oMgS, oDmg, oMdir, oVp, oVs, oScope, oProv, oReason, ...
    'VariableNames', {'fault_location', 'fault_type', 'caseID', 'device_id', ...
    'I_primary_A', 'I_primary_kA', 'relay_path', 'I_sec_primary_A', ...
    'I_sec_sens_A', 'ct_primary', 'ct_legacy', 'ct_tag', 'pickup_primary_A', ...
    'tms', 'curve', 't_primary_s', 't_sens_s', 'dt_s', 'direction', ...
    'margin_primary_s', 'margin_sens_s', 'dmargin_s', 'margin_direction', ...
    'verdict_primary', 'verdict_sens', 'scope', 'provenance', 'reason'});
end

function d = finddev(devices, id)
d = [];
for k = 1:numel(devices)
    did = devices(k).device_id;
    if isstring(did) && isscalar(did), did = char(did); end
    if ischar(did) && strcmp(strtrim(did), id), d = devices(k); return; end
end
error('phase5b_production:devices', 'device %s not found in v2 devices.', id);
end

function ct = read_ct(d, id)
ct = double(d.ct_ratio);
if ~(isscalar(ct) && isfinite(ct) && ct > 0)
    error('phase5b_production:sensitivity', 'device %s needs finite ct_ratio > 0 (v2 device CT, read never hard-coded).', id);
end
end

function pk = read_pickup(d, id)
pk = double(d.pickup_A);
if ~(isscalar(pk) && isfinite(pk) && pk > 0)
    error('phase5b_production:sensitivity', 'device %s needs finite stamped pickup_A > 0 (C4-resolved, read never hard-coded).', id);
end
end

function [tms, cv] = read_tc(d, id)
tm = double(d.tms);
if ~(isscalar(tm) && isfinite(tm) && tm > 0)
    error('phase5b_production:sensitivity', 'device %s needs finite stamped tms > 0 (C4-resolved, read never hard-coded).', id);
end
tms = tm;
cv = d.curve;
if isstring(cv) && isscalar(cv), cv = char(cv); end
if ischar(cv) && ~isempty(strtrim(cv))
    cv = upper(strtrim(cv));
else
    cv = 'SI';
end
end

function t = sidetime(Isec, IsSec, tms, cv)
if ~isscalar(Isec) || ~isreal(Isec) || ~isfinite(Isec) || Isec < 0
    t = NaN;
    return;
end
t = phase5_time(Isec, IsSec, tms, cv);
end

function [mg, vd] = pairverdict(tDown, tUp, CTI)
if ~isfinite(tDown) || ~isfinite(tUp)
    mg = NaN;
    vd = 'NO-TRIP';
    return;
end
mg = tUp - tDown;
if mg >= CTI
    vd = 'PASS';
else
    vd = 'FAIL';
end
end

function [mg, vd] = nopairverdict(tDown)
mg = NaN;
if ~isfinite(tDown)
    vd = 'NO-TRIP';
else
    vd = 'NO-PAIR';
end
end

function [vP, vS, note] = earthverdicts(tP, tS, missN, isGenZone, loc, typ, cs)
if missN
    if isGenZone
        vP = 'NO-TRIP';
        vS = 'NO-TRIP';
        note = sprintf(['NO-TRIP: relay current NOT DETERMINABLE (I0 missing for %s %s %s;' ...
            ' NOT DETERMINABLE FROM AVAILABLE DATA detail)-never-forced-PASS;' ...
            'upstream earth element has no residual CT'], loc, typ, cs);
    else
        vP = 'NOT DETERMINABLE FROM AVAILABLE DATA';
        vS = 'NOT DETERMINABLE FROM AVAILABLE DATA';
        note = sprintf(['NOT DETERMINABLE FROM AVAILABLE DATA: NER leg missing for %s %s %s;' ...
            ' generator earth current cannot be determined, never invented'], loc, typ, cs);
    end
    return;
end
if isfinite(tP)
    vP = 'NOT DETERMINABLE FROM AVAILABLE DATA';
else
    vP = 'NO-TRIP';
end
if isfinite(tS)
    vS = 'NOT DETERMINABLE FROM AVAILABLE DATA';
else
    vS = 'NO-TRIP';
end
if strcmp(vP, 'NOT DETERMINABLE FROM AVAILABLE DATA') || strcmp(vS, 'NOT DETERMINABLE FROM AVAILABLE DATA')
    note = ['NOT DETERMINABLE FROM AVAILABLE DATA: upstream earth element has no residual CT;' ...
        ' downstream 3I0 trip cannot assert backup coordination, never invented'];
else
    note = ['NO-TRIP: downstream below pickup (HV-fault earth delta block or light earth)' ...
        ' - never-forced-PASS'];
end
end

function [dt, dir] = classdir(tP, tS)
if isnan(tP) && isnan(tS)
    dt = NaN;
    dir = 'NOT-DETERMINABLE';
elseif isnan(tP) || isnan(tS)
    dt = NaN;
    dir = 'NOT-DETERMINABLE';
elseif isinf(tP) && isinf(tS)
    dt = 0;
    dir = 'unchanged-no-trip';
elseif isfinite(tP) && isinf(tS)
    dt = Inf;
    dir = 'slower-no-trip';
elseif isinf(tP) && isfinite(tS)
    dt = -Inf;
    dir = 'faster-trip';
else
    dt = tS - tP;
    if abs(dt) <= 1e-9
        dir = 'unchanged';
    elseif dt > 0
        dir = 'slower';
    else
        dir = 'faster';
    end
end
end

function [dmg, mdir] = classmargin(mgP, mgS)
if isfinite(mgP) && isfinite(mgS)
    dmg = mgS - mgP;
    if abs(dmg) <= 1e-9
        mdir = 'unchanged';
    elseif dmg < 0
        mdir = 'tighter';
    else
        mdir = 'wider';
    end
else
    dmg = NaN;
    mdir = 'N/A';
end
end

function v = legcol(Tsec, name, n)
%LEGCOL  Branch-leg column (kA) or NaN vector when absent.
if any(strcmp(Tsec.Properties.VariableNames, name))
    v = double(Tsec.(name)(:));
    if numel(v) ~= n, v = NaN(n, 1); end
else
    v = NaN(n, 1);
end
end

function c = tocell(v)
%TOCELL  Normalize table/struct text to cellstr.
if iscell(v)
    c = v(:);
    for k = 1:numel(c)
        if isstring(c{k}) && isscalar(c{k}), c{k} = char(c{k}); end
    end
elseif isstring(v)
    c = cellstr(v(:));
elseif ischar(v)
    c = cellstr(v);
else
    error('phase5b_production:schema', 'text column must be cell/string/char.');
end
end

function S = phase5b_tcc(varargin)
%PHASE5B_TCC  Two-class TCC plots: physical DT vs study SI (Phase-5b Task C10).
%   S = PHASE5B_TCC() writes two headless figures under v2 plots:
%     results/phase5_protection_v2/plots/tcc_physical.png  Class A physical:
%       GEN definite-time I> vertical at 17171 A primary (1.1447 A via
%       15000/1) + horizontal 3 s line DASHED and labelled ?? 
%       PENDING-COORDINATION (never solid); 87G pickup band marker at
%       0.20pu approx 2403.8 A (vertical band, no curve invented).
%     results/phase5_protection_v2/plots/tcc_study.png  Class B study:
%       SI curves TMS 0.20 with v2 pickups via 1600/1 CTs (GEN 17170.8 A,
%       GSUT 1380 A, GIS 1.2xFL formula) using frozen phase5_curve
%       read-only (never hard-coded times).
%   S = PHASE5B_TCC(outDir) writes into outDir; S = PHASE5B_TCC(outDir, root)
%   resolves v2 registry against root (default ashuganj_root()).
%   Curves come from the locked library only: settings via PHASE5B_REGISTRY
%   + PHASE5B_PICKUP (baseline DT + study SI rules), times via PHASE5_CURVE
%   / PHASE5_TIME (never hard-coded). No maker strings in titles/labels/
%   footers (study values only). Classes in SEPARATE files. Figures are
%   headless-safe (Visible off). All errors are phase5b-prefixed.
if nargin == 0
    root = ashuganj_root();
    outDir = fullfile(root, 'results', 'phase5_protection_v2', 'plots');
elseif nargin == 1
    outDir = varargin{1};
    root = ashuganj_root();
elseif nargin == 2
    outDir = varargin{1};
    root = varargin{2};
else
    error('phase5b_tcc:args', 'usage: S = phase5b_tcc() or phase5b_tcc(outDir) or phase5b_tcc(outDir, root).');
end
if isstring(outDir) && isscalar(outDir), outDir = char(outDir); end
if isstring(root) && isscalar(root), root = char(root); end
if ~ischar(outDir) || isempty(strtrim(outDir))
    error('phase5b_tcc:args', 'outDir must be a non-empty path (char).');
end
if ~ischar(root) || isempty(strtrim(root))
    error('phase5b_tcc:args', 'root must be a non-empty project-root path (char).');
end
if exist(root, 'dir') ~= 7
    error('phase5b_tcc:root', 'project root not found: %s', root);
end
if exist(outDir, 'dir') ~= 7
    [okMk, msgMk] = mkdir(outDir);
    if ~okMk
        error('phase5b_tcc:mkdir', 'cannot create outDir %s (%s).', outDir, msgMk);
    end
end
% --- v2 registry + pickup engine (live, never hard-coded) ---
R = phase5b_registry();
bl = find_by_ansi_layer(R.devices, '50/51-DT', 'PHYSICAL');
d87 = find_by_ansi_layer(R.devices, '87G', 'PHYSICAL');
FL_GENQ_A = 9.47574312698307 * 1000;
IMIN_PHASE_A = 43758.8597559;
Pb = phase5b_pickup(bl, FL_GENQ_A, IMIN_PHASE_A);
dt_Is_prim = Pb.setting;
dt_Is_sec = Pb.setting_sec_A;
tdef_s = Pb.tdef;
pickup_87G_A = double(d87.pickup_A);
pickup_87G_pu = 0.20;
% Study anchors (documented FL anchors; settings recomputed live below).
ILOAD_GSUT_A = 870.772573866956;
ILOAD_Q0_A = 869.956651959241;
dGen = find_by_id(R.devices, 'GEN-51');
dHv = find_by_id(R.devices, 'GSUT-HV-51');
dQ0 = find_by_id(R.devices, 'GIS-Q0-51');
Pg = phase5b_pickup(dGen, FL_GENQ_A, IMIN_PHASE_A);
Ph = phase5b_pickup(dHv, ILOAD_GSUT_A, IMIN_PHASE_A);
Pq = phase5b_pickup(dQ0, ILOAD_Q0_A, IMIN_PHASE_A);
sGen = mk_study_setting('GEN-51', dGen, Pg);
sHv = mk_study_setting('GSUT-HV-51', dHv, Ph);
sQ0 = mk_study_setting('GIS-Q0-51', dQ0, Pq);
study_settings = [sGen, sHv, sQ0];
study_times = zeros(1, 3);
for k = 1:3
    s = study_settings(k);
    study_times(k) = phase5_time(2*s.pickup_sec, s.pickup_sec, s.TMS, s.curve);
end
% --- Class A physical figure ---
dt_label = sprintf('GEN DT I> | CT 15000/1 | Is %.4g A-prim (%.4g A-sec) | DT-?? ?? PENDING-COORDINATION', dt_Is_prim, dt_Is_sec);
tdef_label = sprintf('tdef %.2f s ?? PENDING-COORDINATION (dashed, never solid)', tdef_s);
band_label = sprintf('GEN 87G pickup band 0.20pu approx %.1f A-prim (no curve invented)', pickup_87G_A);
physical_labels = {dt_label, tdef_label, band_label};
physical_title = 'Phase-5b physical TCC (DT baseline + 87G band, ?? PENDING-COORDINATION)';
physical_foot = {'PHYSICAL baseline: DT I> ON, inverse disabled; timing NOT-DETERMINABLE ?? PENDING-COORDINATION', ...
    '87G start 0.20pu band only, no curve invented; trip paths NOT-DETERMINABLE'};
physPng = fullfile(outDir, 'tcc_physical.png');
draw_physical(dt_Is_prim, tdef_s, pickup_87G_A, dt_label, tdef_label, band_label, physical_title, physical_foot, physPng);
% --- Class B study figure ---
study_labels = cell(1, 3);
for k = 1:3
    s = study_settings(k);
    study_labels{k} = sprintf('%s | ANSI 51 OC | CT %.0f/1 | Is %.4g A-prim (%.4g A-sec) | TMS %.4g | %s', ...
        s.device_id, s.ct, s.pickup_prim, s.pickup_sec, s.TMS, s.curve);
end
study_title = 'Phase-5b study TCC (SI curves TMS 0.20, v2 pickups)';
study_foot = {'STUDY SI curves TMS 0.20 via 1600/1 CTs (GSUT/GIS) + 15000/1 GEN; IEC 60255 study values', ...
    'Branch-current doctrine; CTI 0.3 s not shown'};
studyPng = fullfile(outDir, 'tcc_study.png');
draw_study(study_settings, study_labels, study_title, study_foot, studyPng);
S = struct('physical_png', physPng, 'study_png', studyPng, ...
    'physical_title', physical_title, 'study_title', study_title, ...
    'physical_labels', {physical_labels}, 'study_labels', {study_labels}, ...
    'physical_foot', {physical_foot}, 'study_foot', {study_foot}, ...
    'dt_Is_prim', dt_Is_prim, 'dt_Is_sec', dt_Is_sec, 'tdef_s', tdef_s, ...
    'dt_label', dt_label, 'tdef_label', tdef_label, ...
    'dt_vline_style', '-', 'dt_hline_style', '--', ...
    'pickup_87G_A', pickup_87G_A, 'pickup_87G_pu', pickup_87G_pu, ...
    'study_settings', study_settings, 'study_times', study_times);
end

function d = find_by_id(devices, id)
d = [];
for k = 1:numel(devices)
    did = devices(k).device_id;
    if isstring(did) && isscalar(did), did = char(did); end
    if ischar(did) && strcmp(strtrim(did), id), d = devices(k); return; end
end
if isempty(d)
    error('phase5b_tcc:devices', 'device %s not found in phase5b_registry.', id);
end
end

function d = find_by_ansi_layer(devices, ansiWant, layerWant)
d = [];
for k = 1:numel(devices)
    a = devices(k).ansi;
    if isstring(a) && isscalar(a), a = char(a); end
    L = devices(k).layer;
    if isstring(L) && isscalar(L), L = char(L); end
    if ischar(a) && ischar(L) && strcmp(strtrim(a), ansiWant) && strcmp(strtrim(L), layerWant)
        d = devices(k); return;
    end
end
if isempty(d)
    error('phase5b_tcc:devices', 'ansi %s layer %s not found in phase5b_registry.', ansiWant, layerWant);
end
end

function s = mk_study_setting(id, devRow, P)
ct = double(devRow.ct_ratio);
if ~(isscalar(ct) && isfinite(ct) && ct > 0)
    error('phase5b_tcc:ct', 'device %s needs finite ct_ratio > 0 (protection CT).', id);
end
s = struct('device_id', id, 'pickup_prim', double(P.setting), ...
    'pickup_sec', double(P.setting_sec_A), 'TMS', double(P.tms), ...
    'curve', char(P.curve), 'ct', ct);
end

function draw_physical(IsPrim, tdef, bandA, dtLabel, tdefLabel, bandLabel, titleStr, footStr, pngPath)
xmin = 500;
xmax = 2e6;
yl = [0.1, 30];
fig = figure('Visible', 'off', 'Color', 'white');
hold on;
% DT vertical (solid) at Is.
loglog([IsPrim, IsPrim], yl, '-', 'Color', [0 0.4470 0.7410], 'LineWidth', 1.6);
text(IsPrim, yl(2), ['  ' dtLabel], 'Color', [0 0.4470 0.7410], 'FontSize', 7, 'VerticalAlignment', 'top', 'Interpreter', 'none');
% tdef horizontal DASHED at 3 s (never solid by contract).
loglog([xmin, xmax], [tdef, tdef], '--', 'Color', [0.8500 0.3250 0.0980], 'LineWidth', 1.6);
text(xmax*0.5, tdef*1.15, ['  ' tdefLabel], 'Color', [0.8500 0.3250 0.0980], 'FontSize', 7, 'Interpreter', 'none');
% 87G band marker (dotted vertical, no curve invented).
loglog([bandA, bandA], yl, ':', 'Color', [0.4660 0.6740 0.1880], 'LineWidth', 1.4);
text(bandA, yl(2)*0.35, ['  ' bandLabel], 'Color', [0.4660 0.6740 0.1880], 'FontSize', 7, 'Interpreter', 'none');
set(gca, 'XScale', 'log', 'YScale', 'log');
xlabel('Current, A primary (log scale)');
ylabel('Time, s (log scale)');
title(titleStr, 'Interpreter', 'none');
legend({dtLabel, tdefLabel, bandLabel}, 'Location', 'best', 'Interpreter', 'none', 'FontSize', 7);
grid on;
xlim([xmin, xmax]);
ylim(yl);
text(xmax*0.98, yl(2)*0.7, footStr, 'FontSize', 7, ...
    'VerticalAlignment', 'top', 'HorizontalAlignment', 'right', ...
    'Interpreter', 'none');
print(fig, pngPath, '-dpng');
close(fig);
if exist(pngPath, 'file') ~= 2
    error('phase5b_tcc:write', 'TCC PNG not written: %s', pngPath);
end
end

function draw_study(settings, labels, titleStr, footStr, pngPath)
n = numel(settings);
IsAll = zeros(1, n);
for k = 1:n
    IsAll(k) = settings(k).pickup_prim;
end
xmin = min(IsAll) * 0.5;
xmax = max(IsAll) * 100;
if ~(isfinite(xmin) && isfinite(xmax) && xmin > 0 && xmax > xmin)
    error('phase5b_tcc:limits', 'non-finite TCC current axis limits.');
end
fig = figure('Visible', 'off', 'Color', 'white');
hold on;
cols = lines(n);
for k = 1:n
    s = settings(k);
    Is = s.pickup_prim;
    lo = Is * 1.005;
    hi = Is * 100;
    I = logspace(log10(lo), log10(hi), 240);
    M = I / Is;
    t = phase5_curve(M, s.curve, s.TMS);
    loglog(I, t, 'Color', cols(k, :), 'LineWidth', 1.6);
end
yl = [0.01, 100];
for k = 1:n
    loglog([IsAll(k), IsAll(k)], yl, '--', 'Color', cols(k, :), 'LineWidth', 1.0);
    if k == 1
        py = yl(2);
    else
        py = yl(2) * 0.35;
    end
    text(IsAll(k), py, sprintf('  Is %s', settings(k).device_id), ...
        'Color', cols(k, :), 'FontSize', 8, 'VerticalAlignment', 'top');
end
set(gca, 'XScale', 'log', 'YScale', 'log');
xlabel('Current, A primary (log scale)');
ylabel('Time, s (log scale)');
title(titleStr, 'Interpreter', 'none');
legend(labels, 'Location', 'best', 'Interpreter', 'none', 'FontSize', 7);
grid on;
xlim([xmin, xmax]);
ylim(yl);
text(xmax*0.98, yl(2)*0.7, footStr, 'FontSize', 7, ...
    'VerticalAlignment', 'top', 'HorizontalAlignment', 'right', ...
    'Interpreter', 'none');
print(fig, pngPath, '-dpng');
close(fig);
if exist(pngPath, 'file') ~= 2
    error('phase5b_tcc:write', 'TCC PNG not written: %s', pngPath);
end
end

function W = phase5b_writer(outDir, tables, meta)
%PHASE5B_WRITER  v2 CSV/manifest/sha256/run_log writer (Phase-5b Task C11).
%   W = PHASE5B_WRITER(outDir, tables, meta) writes the ten locked
%   Phase-5b production-v2 tables plus manifest.json, run_log.txt and
%   sha256.txt into outDir (created when missing; files overwritten
%   deterministically). The caller (run_phase5b_production) owns the
%   results/phase5_protection_v2 exists-guard
%   (error('phase5b_production:exists')); this function never deletes
%   anything outside outDir, never touches Phase-4 inputs, and never
%   touches results/phase5_protection (frozen v1 outputs dir).
%
%   tables struct fields (all MATLAB tables, height >= 1):
%     .registry      v2 device_registry (21 v1 fields + physical_CT_ratio,
%                    selected_CT_core, protection_function, study_CT_ratio,
%                    layer + scope = 27 cols; assumption_class PRIMARY is
%                    LEGAL on PHYSICAL rows — C3 concern resolved yes, never
%                    rejected here)
%     .settings      relay_settings (v1 11 cols; study rows carry C4 pickups
%                    17170.8/5/1380/GIS-formula via 15000/1600 CTs, TMS 0.20
%                    phase / 0.15 EF; Siemens DT baseline row carries
%                    curve DT-?? + NaN tms with tdef/time_status in text)
%     .faultInputs   fault_inputs (v1 9 cols; 40-row T40 backbone)
%     .relayCurrents relay_currents (v1 13 cols; v2 CTs 15000 gen / 1600
%                    GSUT-GIS via frozen phase5_ct arithmetic — the frozen
%                    phase5_ct_table wrapper rejects 1600 by its locked ratio
%                    guard, so the driver converts via phase5_ct, the single
%                    source of truth phase5_ct_table delegates to; see the
%                    C11 report concern C11-REL-CT)
%     .coordMatrix   coordination_matrix (v1 17 cols; graded on v2-resolved
%                    devices via frozen phase5_coord; DT-?? baseline rows never
%                    dispatched to phase5_time — excluded with ?? reason)
%     .coordMargins  coordination_margins (v1 9 cols)
%     .duty          breaker_duty (v1 10 cols + equipment_rating_kA +
%                    equipment_basis + provenance + scope = 14 cols; Q0 rows
%                    carry the GIS 50 kA EQUIPMENT WITHSTAND only in equipment
%                    columns, never as interrupting rating; 52G rows carry the
%                    100 kA interrupting rating from phase5b_duty)
%     .sensitivity   sensitivity (v1 28 cols; v2-adapted GEN scope — the frozen
%                    phase5_sensitivity hard-codes the v1 2000 CT on its
%                    upstream leg (IsUp = pkUp/2000, primUp/2000, reason
%                    '2000/1'), so per the C11 ruling it is BLOCKED for v2
%                    reuse (never modified) and the driver computes the
%                    v2-adapted table reading device CTs/pickups; evidence
%                    pinned in test_phase5b_writer)
%     .validation    validation (v1 6 cols; live frozen phase5_validate legs;
%                    v2 legs B01+ arrive in C12 phase5b_validate)
%     .effectiveness NEW phase5b effectiveness table (13 locked C8 cols:
%                    fault_location, fault_type, caseID, primary_function,
%                    primary_availability, primary_time_s, backup_function,
%                    backup_time_s, ct_source, setting_source, detection,
%                    determinable, not_determinable; determinable logical is
%                    written 1/0 for CSV cleanliness)
%
%   meta struct fields:
%     .tag               manifest tag (required non-empty char; production use
%                        'production-v2')
%     .inputManifestSha  SHA-256 of results/phase4_fault/production/
%                        manifest.json, read-only (required non-empty char)
%     .inputShaLines     cellstr copy of production sha256.txt lines
%                        (optional, default {})
%     .v1OutputsManifestSha  SHA-256 of results/phase5_protection/
%                        manifest.json, read-only v1-outputs reference
%                        (required non-empty char)
%     .v1OutputsShaLines cellstr copy of results/phase5_protection/sha256.txt
%                        lines (optional, default {})
%     .validation        struct pass/total/note, live phase5_validate
%                        reference (required)
%     .testCounts        struct NP/NF from run_phase5_tests (required)
%     .settingsLines     cellstr v2 production settings summary for the
%                        run log (required)
%     .extraNotes        cellstr manifest notes appendix (optional)
%     .tcc               struct physical_sha256/study_sha256/regenerated/
%                        physical_png/study_png recording the TCC choice
%                        (regenerate deterministically vs keep + hashes)
%                        (optional, default [])
%
%   Provenance enforcement: every v1-parity table must carry non-empty
%   'provenance' and 'scope' columns; the NEW effectiveness table must carry
%   non-empty ct_source/setting_source/detection/not_determinable (its own
%   traceability — it has no provenance/scope columns by locked C8 schema).
%   Provenance class whitelist (error otherwise):
%   SOURCE-BACKED / DERIVED / ENGINEERING_ASSUMPTION / LEGACY / MISSING /
%   USER_ASSERTED_PENDING_DOC (checked as the prefix before ':' on every
%   provenance cell). assumption_class values are never rejected here.
%
%   sha256.txt covers the 10 CSVs + manifest.json + run_log.txt (12 lines),
%   hex digests via the Java MessageDigest helper (Phase-4 pattern, no
%   toolbox). Code hashes cover every matlab/phase5/*.m sorted by name
%   (hence phase5b_* plus the frozen v1 modules used). All errors are
%   'phase5b'-prefixed.
if nargin ~= 3
    error('phase5b_writer:args', 'usage: W = phase5b_writer(outDir, tables, meta).');
end
if isstring(outDir) && isscalar(outDir), outDir = char(outDir); end
if ~ischar(outDir) || isempty(strtrim(outDir))
    error('phase5b_writer:args', 'outDir must be a non-empty path (char).');
end
names = {'registry', 'settings', 'faultInputs', 'relayCurrents', ...
    'coordMatrix', 'coordMargins', 'duty', 'sensitivity', 'validation', ...
    'effectiveness'};
files = {'phase5_device_registry.csv', 'phase5_relay_settings.csv', ...
    'phase5_fault_inputs.csv', 'phase5_relay_currents.csv', ...
    'phase5_coordination_matrix.csv', 'phase5_coordination_margins.csv', ...
    'phase5_breaker_duty.csv', 'phase5_sensitivity.csv', ...
    'phase5_validation.csv', 'phase5b_effectiveness.csv'};
if ~isstruct(tables) || ~isscalar(tables)
    error('phase5b_writer:args', 'tables must be a scalar struct with the 10 locked table fields.');
end
for k = 1:numel(names)
    if ~isfield(tables, names{k}) || ~istable(tables.(names{k}))
        error('phase5b_writer:schema', 'tables.%s missing or not a table.', names{k});
    end
    if height(tables.(names{k})) < 1
        error('phase5b_writer:rows', 'tables.%s must carry >= 1 row.', names{k});
    end
end
reqCols.registry = {'device_id', 'device_type', 'equipment', 'ansi', 'zone', ...
    'ct_ratio', 'ct_source', 'rated_A', 'vnom_kV', 'fault_source', ...
    'pickup_A', 'tms', 'curve', 'ef_pickup_A', 'ef_tms', 'breaker_ref', ...
    'upstream', 'downstream', 'provenance', 'status', 'assumption_class', ...
    'physical_CT_ratio', 'selected_CT_core', 'protection_function', ...
    'study_CT_ratio', 'layer', 'scope'};
reqCols.settings = {'device_id', 'setting_A_primary', 'unit', 'basis', ...
    'source', 'validation', 'ct_ratio', 'tms', 'curve', 'provenance', 'scope'};
reqCols.faultInputs = {'fault_location', 'fault_type', 'caseID', 'm', ...
    'stage', 'I_primary_kA', 'I_primary_A', 'provenance', 'scope'};
reqCols.relayCurrents = {'fault_location', 'fault_type', 'caseID', ...
    'device_id', 'side', 'I_primary_A', 'I_primary_kA', 'CT_ratio', ...
    'I_secondary_A', 'I0_A', 'I0_source', 'provenance', 'scope'};
reqCols.coordMatrix = {'downstream', 'upstream', 'fault_location', ...
    'fault_type', 'caseID', 'I_fault_kA', 'I_down_A', 'I_up_A', ...
    't_down_s', 't_up_s', 'ct_down', 'ct_up', 'margin_s', 'verdict', ...
    'reason', 'provenance', 'scope'};
reqCols.coordMargins = {'pair', 'fault_location', 'fault_type', 'caseID', ...
    'margin_s', 'verdict', 'reason', 'provenance', 'scope'};
reqCols.duty = {'location', 'breaker_ref', 'fault_type', 'caseID', ...
    'I_sym_kA', 'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
    'equipment_rating_kA', 'equipment_basis', 'provenance', 'scope'};
reqCols.sensitivity = {'fault_location', 'fault_type', 'caseID', ...
    'device_id', 'I_primary_A', 'I_primary_kA', 'relay_path', ...
    'I_sec_primary_A', 'I_sec_sens_A', 'ct_primary', 'ct_legacy', ...
    'ct_tag', 'pickup_primary_A', 'tms', 'curve', 't_primary_s', ...
    't_sens_s', 'dt_s', 'direction', 'margin_primary_s', 'margin_sens_s', ...
    'dmargin_s', 'margin_direction', 'verdict_primary', 'verdict_sens', ...
    'scope', 'provenance', 'reason'};
reqCols.validation = {'leg', 'pass', 'residual', 'note', 'provenance', 'scope'};
reqCols.effectiveness = {'fault_location', 'fault_type', 'caseID', ...
    'primary_function', 'primary_availability', 'primary_time_s', ...
    'backup_function', 'backup_time_s', 'ct_source', 'setting_source', ...
    'detection', 'determinable', 'not_determinable'};
provTables = {'registry', 'settings', 'faultInputs', 'relayCurrents', ...
    'coordMatrix', 'coordMargins', 'duty', 'sensitivity', 'validation'};
for k = 1:numel(names)
    vn = tables.(names{k}).Properties.VariableNames;
    for q = 1:numel(reqCols.(names{k}))
        if ~any(strcmp(vn, reqCols.(names{k}){q}))
            error('phase5b_writer:schema', 'tables.%s missing required column %s.', ...
                names{k}, reqCols.(names{k}){q});
        end
    end
end
for k = 1:numel(provTables)
    assert_ledger(tables.(provTables{k}), provTables{k}, 'provenance');
    assert_ledger(tables.(provTables{k}), provTables{k}, 'scope');
    assert_whitelist(tables.(provTables{k}), provTables{k});
end
assert_ledger(tables.effectiveness, 'effectiveness', 'ct_source');
assert_ledger(tables.effectiveness, 'effectiveness', 'setting_source');
assert_ledger(tables.effectiveness, 'effectiveness', 'detection');
assert_ledger(tables.effectiveness, 'effectiveness', 'not_determinable');
meta = check_meta(meta);
if exist(outDir, 'dir') ~= 7
    [okMk, msgMk] = mkdir(outDir);
    if ~okMk
        error('phase5b_writer:mkdir', 'cannot create outDir %s (%s).', outDir, msgMk);
    end
end
% Logical columns to 1/0 numeric for CSV cleanliness.
Tval = tables.validation;
if islogical(Tval.pass)
    Tval.pass = double(Tval.pass);
end
Teff = tables.effectiveness;
if islogical(Teff.determinable)
    Teff.determinable = double(Teff.determinable);
end
tout.registry = tables.registry;
tout.settings = tables.settings;
tout.faultInputs = tables.faultInputs;
tout.relayCurrents = tables.relayCurrents;
tout.coordMatrix = tables.coordMatrix;
tout.coordMargins = tables.coordMargins;
tout.duty = tables.duty;
tout.sensitivity = tables.sensitivity;
tout.validation = Tval;
tout.effectiveness = Teff;
for k = 1:numel(names)
    writetable(tout.(names{k}), fullfile(outDir, files{k}));
end
% Code hashes: every matlab/phase5/*.m sorted by name (Java helper).
% This set is phase5b_* plus the frozen v1 modules used (never modified).
root = ashuganj_root();
mlist = dir(fullfile(root, 'matlab', 'phase5', '*.m'));
mlist = mlist(~[mlist.isdir]);
[~, sord] = sort({mlist.name});
mlist = mlist(sord);
codeHashes = struct('file', {}, 'sha256', {});
for k = 1:numel(mlist)
    codeHashes(end + 1) = struct('file', mlist(k).name, ... %#ok<AGROW>
        'sha256', sha256file(fullfile(root, 'matlab', 'phase5', mlist(k).name)));
end
rowCounts = struct('phase5_device_registry_csv', height(tout.registry), ...
    'phase5_relay_settings_csv', height(tout.settings), ...
    'phase5_fault_inputs_csv', height(tout.faultInputs), ...
    'phase5_relay_currents_csv', height(tout.relayCurrents), ...
    'phase5_coordination_matrix_csv', height(tout.coordMatrix), ...
    'phase5_coordination_margins_csv', height(tout.coordMargins), ...
    'phase5_breaker_duty_csv', height(tout.duty), ...
    'phase5_sensitivity_csv', height(tout.sensitivity), ...
    'phase5_validation_csv', height(tout.validation), ...
    'phase5b_effectiveness_csv', height(tout.effectiveness));
vref = sprintf('%d/%d', meta.validation.pass, meta.validation.total);
manifest = struct( ...
    'tag', meta.tag, ...
    'timestamp_local', datestr(now, 'yyyy-mm-ddTHH:MM:SS'), ...
    'input', struct('productionManifestSha256', meta.inputManifestSha, ...
        'productionSha256Txt', {meta.inputShaLines}, ...
        'source', 'results/phase4_fault/production (read-only; never modified)', ...
        'v1OutputsManifestSha256', meta.v1OutputsManifestSha, ...
        'v1OutputsSha256Txt', {meta.v1OutputsShaLines}, ...
        'v1OutputsSource', 'results/phase5_protection (read-only reference; frozen v1 outputs, never modified)'), ...
    'rowCounts', rowCounts, ...
    'files', {{files{1}, files{2}, files{3}, files{4}, files{5}, files{6}, ...
        files{7}, files{8}, files{9}, files{10}, 'manifest.json', 'run_log.txt'}}, ...
    'codeHashes', codeHashes, ...
    'validation', struct('runner', 'phase5_validate', 'reference', vref, ...
        'pass', meta.validation.pass, 'total', meta.validation.total, ...
        'note', meta.validation.note), ...
    'testCounts', struct('runner', 'run_phase5_tests', ...
        'NP', meta.testCounts.NP, 'NF', meta.testCounts.NF), ...
    'settings', {meta.settingsLines}, ...
    'notes', {{['Phase-5b physical-alignment correction on frozen Phase-4 production data; ' ...
        'v2 study settings (C4 pickups via 15000/1600 CTs, TMS 0.20 phase / 0.15 EF) + ' ...
        'PHYSICAL presence rows (settings only where sourced); Siemens DT baseline ' ...
        'never dispatched to inverse time; ip peak is borrowed-shape design-defined, ' ...
        'never a breaker-duty input; v1 outputs dir frozen untouched.'], meta.extraNotes{:}}});
if ~isempty(meta.tcc)
    manifest.tccPlots = meta.tcc;
end
fid = fopen(fullfile(outDir, 'manifest.json'), 'w');
if fid < 0
    error('phase5b_writer:write', 'Cannot write manifest.json.');
end
fprintf(fid, '%s', jsonencode(manifest, 'PrettyPrint', true));
fclose(fid);
% Run log: settings + row counts + validation/test references.
logL = {};
logL{end + 1} = sprintf('run_phase5b_production %s written %s (local)', ... %#ok<AGROW>
    meta.tag, datestr(now, 'yyyy-mm-ddTHH:MM:SS'));
logL{end + 1} = sprintf('input production manifest SHA-256: %s', meta.inputManifestSha); %#ok<AGROW>
logL{end + 1} = sprintf('v1 outputs manifest SHA-256 (read-only reference): %s', meta.v1OutputsManifestSha); %#ok<AGROW>
logL{end + 1} = 'settings (C4 production-v2 path; study settings, never tuned-to-pass):'; %#ok<AGROW>
for k = 1:numel(meta.settingsLines)
    logL{end + 1} = sprintf('  %s', meta.settingsLines{k}); %#ok<AGROW>
end
rc = fieldnames(rowCounts);
for k = 1:numel(rc)
    logL{end + 1} = sprintf('rows %s = %d', rc{k}, rowCounts.(rc{k})); %#ok<AGROW>
end
logL{end + 1} = sprintf('validation live phase5_validate: %s (%s)', vref, meta.validation.note); %#ok<AGROW>
logL{end + 1} = sprintf('tests run_phase5_tests: NP=%d NF=%d', ... %#ok<AGROW>
    meta.testCounts.NP, meta.testCounts.NF);
if ~isempty(meta.tcc)
    logL{end + 1} = sprintf('TCC choice: %s', meta.tcc.choice_note); %#ok<AGROW>
    logL{end + 1} = sprintf('TCC hashes: tcc_physical.png %s; tcc_study.png %s', ... %#ok<AGROW>
        meta.tcc.physical_sha256, meta.tcc.study_sha256);
end
logL{end + 1} = 'sha256.txt written after this log; it covers the 10 CSVs + manifest.json + this log.'; %#ok<AGROW>
fid = fopen(fullfile(outDir, 'run_log.txt'), 'w');
if fid < 0
    error('phase5b_writer:write', 'Cannot write run_log.txt.');
end
for k = 1:numel(logL)
    fprintf(fid, '%s\n', logL{k});
end
fclose(fid);
% sha256 over the 10 CSVs + manifest + run log.
hashFiles = [files, {'manifest.json', 'run_log.txt'}];
fid = fopen(fullfile(outDir, 'sha256.txt'), 'w');
if fid < 0
    error('phase5b_writer:write', 'Cannot write sha256.txt.');
end
for k = 1:numel(hashFiles)
    fprintf(fid, '%s  %s\n', sha256file(fullfile(outDir, hashFiles{k})), hashFiles{k});
end
fclose(fid);
W = struct('outDir', outDir, 'tag', meta.tag, 'files', {hashFiles}, ...
    'rowCounts', rowCounts, 'validation', meta.validation, ...
    'testCounts', meta.testCounts);
end

function meta = check_meta(meta)
%CHECK_META  Required meta fields with loud phase5b-prefixed errors.
if ~isstruct(meta) || ~isscalar(meta)
    error('phase5b_writer:args', 'meta must be a scalar struct (tag/validation/testCounts/settingsLines/...).');
end
if ~isfield(meta, 'tag')
