function c = as_lines(v, nm)
%AS_LINES  Normalize a cellstr/string/char setting block to cellstr.
if isstring(v), v = cellstr(v(:)); end
if ischar(v), v = cellstr(v); end
if ~iscell(v) || isempty(v)
    error('phase5b_writer:args', '%s must be a non-empty cellstr.', nm);
end
c = v(:)';
for k = 1:numel(c)
    if isstring(c{k}) && isscalar(c{k}), c{k} = char(c{k}); end
    if ~ischar(c{k})
        error('phase5b_writer:args', '%s entries must be char/string.', nm);
    end
end
end

function assert_ledger(T, tname, col)
%ASSERT_LEDGER  Column present + every row non-empty (provenance full close).
if ~any(strcmp(T.Properties.VariableNames, col))
    error('phase5b_writer:schema', 'tables.%s missing required column %s.', tname, col);
end
v = T.(col);
ok = true;
if iscell(v)
    for i = 1:numel(v)
        vv = v{i};
        if isstring(vv) && isscalar(vv), vv = char(vv); end
        if ~ischar(vv) || isempty(strtrim(vv)), ok = false; break; end
    end
elseif isstring(v)
    for i = 1:numel(v)
        if strlength(strtrim(v(i))) == 0, ok = false; break; end
    end
elseif ischar(v)
    if isempty(strtrim(v)), ok = false; end
else
    ok = false;
end
if ~ok
    error('phase5b_writer:provenance', ...
        'tables.%s has an empty %s cell (every row needs provenance + scope traceability).', tname, col);
end
end

function assert_whitelist(T, tname)
%ASSERT_WHITELIST  Provenance class whitelist (error otherwise).
%   Legal classes: SOURCE-BACKED / DERIVED / ENGINEERING_ASSUMPTION /
%   LEGACY / MISSING / USER_ASSERTED_PENDING_DOC (checked as the prefix
%   before ':'). assumption_class values are never rejected here, and
%   assumption_class PRIMARY on PHYSICAL registry rows is explicitly legal
%   (C3 concern resolved: yes).
legal = {'SOURCE-BACKED', 'DERIVED', 'ENGINEERING_ASSUMPTION', ...
    'LEGACY', 'MISSING', 'USER_ASSERTED_PENDING_DOC'};
v = T.provenance;
for i = 1:numel(v)
    vv = v{i};
    if isstring(vv) && isscalar(vv), vv = char(vv); end
    if ~ischar(vv)
        error('phase5b_writer:provenance', ...
            'tables.%s provenance row %d is not text (whitelist cannot be checked).', tname, i);
    end
    cls = strtok(vv, ':');
    if ~any(strcmp(strtrim(cls), legal))
        error('phase5b_writer:provenance', ...
            'tables.%s provenance row %d class ''%s'' not in whitelist (SOURCE-BACKED/DERIVED/ENGINEERING_ASSUMPTION/LEGACY/MISSING/USER_ASSERTED_PENDING_DOC).', ...
            tname, i, cls);
    end
end
end

function hex = sha256file(path)
%SHA256FILE  SHA-256 hex digest via Java MessageDigest (no toolbox).
md = java.security.MessageDigest.getInstance('SHA-256');
jpath = java.io.File(path).toPath();
md.update(java.nio.file.Files.readAllBytes(jpath));
dig = md.digest();
bi = java.math.BigInteger(1, dig);
hex = char(bi.toString(16));
hex = [repmat('0', 1, 64 - numel(hex)) hex];
end

