function TiJ = join_production_peaks(root, Ti)
%JOIN_PRODUCTION_PEAKS  Iseq0_kA + r_kappa_ip from currents CSV (v1 T(b)+(c)).
%   Backbone-first dedup identical to phase5_import, inner join on
%   (caseID,location,fault_type). Every import row must hit, else
%   phase5b_production:join (never silently NaN-filled).
Fp = fullfile(root, 'results', 'phase4_fault', 'production', 'phase4_fault_currents.csv');
C = readtable(Fp);
for k = 1:numel({'fault_type', 'location', 'm', 'caseID', 'stage', 'Iseq0_kA', 'r_kappa_ip'})
    need = {'fault_type', 'location', 'm', 'caseID', 'stage', 'Iseq0_kA', 'r_kappa_ip'};
    if ~any(strcmp(C.Properties.VariableNames, need{k}))
        error('phase5b_production:schema', 'production currents CSV missing column %s.', need{k});
    end
end
Cb = C(strcmp(C.stage, 'Ikpp') & C.m == 0.5, :);
keys = strcat(Cb.caseID, '|', Cb.location, '|', Cb.fault_type);
[~, ia] = unique(keys, 'stable');
Cb = Cb(ia, :);
n = height(Ti);
Iseq0 = NaN(n, 1); rkp = NaN(n, 1);
tloc = tocell(Ti.fault_location); ttyp = tocell(Ti.fault_type); tcs = tocell(Ti.caseID);
bloc = tocell(Cb.location); btyp = tocell(Cb.fault_type); bcs = tocell(Cb.caseID);
for i = 1:n
    hit = find(strcmp(bcs, tcs{i}) & strcmp(bloc, tloc{i}) & strcmp(btyp, ttyp{i}), 1, 'first');
    if isempty(hit)
        error('phase5b_production:join', ...
            'production currents join missed %s %s %s (backbone keys diverged).', ...
            tcs{i}, tloc{i}, ttyp{i});
    end
    Iseq0(i) = Cb.Iseq0_kA(hit);
    rkp(i) = Cb.r_kappa_ip(hit);
end
if any(~isfinite(Iseq0)) || any(~isfinite(rkp))
    error('phase5b_production:join', 'joined Iseq0_kA/r_kappa_ip must be finite on all 40 backbone rows.');
end
TiJ = Ti;
TiJ.Iseq0_kA = Iseq0;
TiJ.r_kappa_ip = rkp;
end

function anchors = read_anchors(root)
%READ_ANCHORS  Frozen-flow FL_anchor_kA per through_path, live from ct_data.
G = readtable(fullfile(root, 'results', 'phase4_fault', 'production', 'phase4_ct_data.csv'));
if ~all(ismember({'through_path', 'FL_anchor_kA'}, G.Properties.VariableNames))
    error('phase5b_production:schema', 'production ct_data CSV missing through_path/FL_anchor_kA.');
end
paths = {'GEN_Q', 'GSUT_HV', 'GRID_Q', 'LINE_Q9'};
anchors = struct();
tp = tocell(G.through_path);
for k = 1:numel(paths)
    u = unique(G.FL_anchor_kA(strcmp(tp, paths{k})));
    u = u(isfinite(u));
    if numel(u) ~= 1
        error('phase5b_production:anchor', ...
            'through_path %s must carry exactly one FL_anchor_kA (got %d).', paths{k}, numel(u));
    end
    anchors.(paths{k}) = u;
end
end

function [IminPhase, IminEarth] = pickup_anchors(TiJ)
%PICKUP_ANCHORS  Must-detect anchors (v1 T6 convention, totals-based).
%   IminPhase: min over phase-fault totals (LLL/LL/LLG, never LG earth).
%   IminEarth: LG-only min over LG totals (phase5b_pickup EF contract).
typs = tocell(TiJ.fault_type);
ph = strcmp(typs, 'LLL') | strcmp(typs, 'LL') | strcmp(typs, 'LLG');
IfA = double(TiJ.I_primary_A(:));
if any(ph)
    IminPhase = min(IfA(ph));
else
    IminPhase = min(IfA);
end
lg = strcmp(typs, 'LG');
if any(lg)
    IminEarth = min(IfA(lg));
else
    IminEarth = 7.27200442799167;
end
end

function [devicesProd, setRows, settingsLines] = production_settings_v2(Rreg, anchors, IminPhase, IminEarth)
%PRODUCTION_SETTINGS_V2  (c): C4 pickups stamped on a devices copy.
%   Registry struct itself never edited. Siemens-baseline rows NEVER
%   dispatched to phase5_time (asserted use_phase5_time false; no time call).
devs = Rreg.devices;
ids = {devs.device_id};
dGen = devs(strcmp(ids, 'GEN-51'));
dEf = devs(strcmp(ids, 'GEN-51N'));
dHv = devs(strcmp(ids, 'GSUT-HV-51'));
dQ0 = devs(strcmp(ids, 'GIS-Q0-51'));
dBl = devs(strcmp(ids, 'GEN-51-SIEMENS-BL'));
% GEN-51-SI: 1.20 x Imax 14309 = 17170.8 A (max-operating-current basis).
Pgen = phase5b_pickup(dGen, double(Rreg.gen.Imax_A), IminPhase);
if abs(Pgen.setting - 17170.8) / 17170.8 > 1e-9
    error('phase5b_production:pickup', 'GEN-51 v2 pickup %.4f A ~= 17170.8 A.', Pgen.setting);
end
if abs(Pgen.tms - 0.20) > 1e-12 || ~strcmp(Pgen.curve, 'SI') || ~Pgen.use_phase5_time
    error('phase5b_production:pickup', 'GEN-51 v2 must be SI/TMS-0.20/inverse-allowed.');
end
if abs(Pgen.setting_sec_A - Pgen.setting / 15000) / Pgen.setting_sec_A > 1e-12
    error('phase5b_production:pickup', 'GEN-51 secondary must be Is/15000.');
end
% GEN-51N-SI-STUDY: 5 A retained sensitive case; EF TMS 0.15 FROM PICKUP
% (registry GEN-51N tms is 0.20 — the pickup value governs, asserted here).
Pef = phase5b_pickup(dEf, 0, IminEarth);
if abs(Pef.setting - 5) > 1e-12
    error('phase5b_production:pickup', 'GEN-51N v2 pickup %.6f A ~= 5 A.', Pef.setting);
end
if abs(Pef.tms - 0.15) > 1e-12 || abs(Pef.ef_tms - 0.15) > 1e-12
    error('phase5b_production:pickup', 'GEN-51N v2 EF TMS must be 0.15 from pickup (not registry 0.20).');
end
if abs(double(dEf.tms) - 0.20) > 1e-12
    error('phase5b_production:pickup', 'GEN-51N registry tms must be 0.20 (EF 0.15 comes from pickup).');
end
% GSUT-HV-51: 1.2 x max(rated 1150 A, GSUT_HV anchor) = 1380 A via 1600/1.
hvAnchor = anchors.GSUT_HV * 1000;
Phv = phase5b_pickup(dHv, hvAnchor, IminPhase);
if abs(Phv.setting - 1380) / 1380 > 1e-9
    error('phase5b_production:pickup', 'GSUT-HV-51 v2 pickup %.4f A ~= 1380 A.', Phv.setting);
end
if abs(Phv.tms - 0.20) > 1e-12 || ~strcmp(Phv.curve, 'SI') || ~Phv.use_phase5_time
    error('phase5b_production:pickup', 'GSUT-HV-51 v2 must be SI/TMS-0.20/inverse-allowed.');
end
if abs(Phv.setting_sec_A - 1380 / 1600) / (1380 / 1600) > 1e-12
    error('phase5b_production:pickup', 'GSUT-HV-51 secondary must be 1380/1600.');
end
% GIS-Q0-51 V2 PATH: 1.2 x LINE_Q9 FL_anchor via 1600/1 (GIS formula).
q0Anchor = anchors.LINE_Q9 * 1000;
Pq0 = phase5b_pickup(dQ0, q0Anchor, IminPhase);
if abs(Pq0.setting / q0Anchor - 1.2) > 1e-12
    error('phase5b_production:pickup', 'GIS-Q0-51 v2 pickup must be 1.2x FL_anchor.');
end
if abs(Pq0.tms - 0.20) > 1e-12 || ~strcmp(Pq0.curve, 'SI') || ~Pq0.use_phase5_time
    error('phase5b_production:pickup', 'GIS-Q0-51 v2 must be SI/TMS-0.20/inverse-allowed.');
end
if abs(Pq0.setting_sec_A - Pq0.setting / 1600) / Pq0.setting_sec_A > 1e-12
    error('phase5b_production:pickup', 'GIS-Q0-51 secondary must be Is/1600.');
end
% Siemens DT baseline: resolved for the settings RECORD ONLY — inverse
% prohibited (use_phase5_time false asserted; never dispatched to phase5_time).
Pbl = phase5b_pickup(dBl, anchors.GEN_Q * 1000, IminPhase);
if abs(Pbl.setting - 17171) > 1e-9
    error('phase5b_production:pickup', 'GEN-51-SIEMENS-BL pickup %.4f A ~= 17171 A.', Pbl.setting);
end
if ~(islogical(Pbl.use_phase5_time) && isscalar(Pbl.use_phase5_time) && ~Pbl.use_phase5_time)
    error('phase5b_production:pickup', 'GEN-51-SIEMENS-BL must carry use_phase5_time false (inverse prohibited).');
end
if ~strcmp(Pbl.curve, 'DT-??')
    error('phase5b_production:pickup', 'GEN-51-SIEMENS-BL must carry curve DT-??.');
end
% Stamp resolved pickup/TMS/curve into a copy (registry never edited).
% EF TMS 0.15 from pickup (not registry 0.20) is stamped into .tms so the
% frozen coord/time path grades the pickup-consistent dial.
devicesProd = devs;
devicesProd(strcmp(ids, 'GEN-51')).pickup_A = Pgen.setting;
devicesProd(strcmp(ids, 'GEN-51')).tms = Pgen.tms;
devicesProd(strcmp(ids, 'GEN-51')).curve = Pgen.curve;
devicesProd(strcmp(ids, 'GEN-51N')).pickup_A = Pef.setting;
devicesProd(strcmp(ids, 'GEN-51N')).tms = Pef.tms;
devicesProd(strcmp(ids, 'GEN-51N')).curve = Pef.curve;
devicesProd(strcmp(ids, 'GSUT-HV-51')).pickup_A = Phv.setting;
devicesProd(strcmp(ids, 'GSUT-HV-51')).tms = Phv.tms;
devicesProd(strcmp(ids, 'GSUT-HV-51')).curve = Phv.curve;
devicesProd(strcmp(ids, 'GIS-Q0-51')).pickup_A = Pq0.setting;
devicesProd(strcmp(ids, 'GIS-Q0-51')).tms = Pq0.tms;
devicesProd(strcmp(ids, 'GIS-Q0-51')).curve = Pq0.curve;
setRows = settings_table_v2(devs, Pgen, Pef, Phv, Pq0, Pbl);
settingsLines = {
    sprintf('GEN-51-SI phase pickup %.2f A-primary (1.20xImax-14309A max-operating-current; %s)', Pgen.setting, Pgen.basis)
    sprintf('GEN-51-SI secondary %.5f A via 15000/1 (converges with Siemens DT 17171 A; characteristic SI-vs-DT differs)', Pgen.setting_sec_A)
    sprintf('GEN-51N-SI-STUDY earth pickup %.2f A-primary (SENSITIVE retained; %s)', Pef.setting, Pef.basis)
    sprintf('GEN-51N-SI-STUDY TMS %.2f from phase5b_pickup (NOT registry 0.20); secondary %.6f A via 15000/1', Pef.tms, Pef.setting_sec_A)
    sprintf('GSUT-HV-51 phase pickup %.2f A-primary (1.2xmax(rated 1150 A, GSUT_HV anchor %.4f A) via 1600/1 SOURCE-BACKED; %s)', Phv.setting, hvAnchor, Phv.source)
    sprintf('GSUT-HV-51 secondary %.4f A (1380/1600)', Phv.setting_sec_A)
    sprintf('GIS-Q0-51 phase pickup %.4f A-primary (V2 1.2x LINE_Q9 FL_anchor %.6f A from phase4_ct_data.csv via 1600/1 SOURCE-BACKED; never 2400 A rated-proxy)', Pq0.setting, q0Anchor)
    sprintf('GIS-Q0-51 secondary %.6f A (Is/1600)', Pq0.setting_sec_A)
    sprintf('GEN-51-SIEMENS-BL DT baseline %.0f A-primary (%.4f A-sec via 15000/1; tdef %.2f s ?? PENDING-COORDINATION; inverse PROHIBITED — never dispatched to phase5_time)', Pbl.setting, Pbl.setting_sec_A, Pbl.tdef)
    sprintf('FL anchors (phase4_ct_data.csv FL_anchor_kA, frozen flows): GEN_Q %.4f, GSUT_HV %.5f, GRID_Q %.5f, LINE_Q9 %.6f kA', anchors.GEN_Q, anchors.GSUT_HV, anchors.GRID_Q, anchors.LINE_Q9)
    sprintf('Imin anchors: phase %.2f A (LLL/LL/LLG totals min); earth %.5f A (LG totals min per EF contract)', IminPhase, IminEarth)
    'TMS study uniform 0.20 phase (ENGINEERING_ASSUMPTION Status-C initial, registry-stamped) / 0.15 EF (pickup-resolved); curve SI (STUDY constants, never manufacturer)'
    'CTI 0.3 s SOURCE-BACKED confirmed (ledger CTI-0.3s); v2 CTs 15000/1 GEN + 1600/1 GSUT-GIS SOURCE-BACKED, 16000/1 LEGACY fenced sensitivity only'
    'Breaker duty: Q0 (52-1) NOT DETERMINABLE interrupting + 52G/GCB-10BAC10 100 kA sym breaking SOURCE-BACKED; peak r_kappa_ip borrowed-shape informational only, never duty input'
    'CSV dialect: RFC-4180 comma-separated; text fields with commas are double-quoted. MATLAB readers must use readtable(fp,''Delimiter'','','') because the auto-delimiter sniffer misparses quoted-comma rows.'
    };
end

