function Trc = relay_currents_table_v2(Mtrx, TiJ)
%RELAY_CURRENTS_TABLE_V2  One row per finite matrix side + I0 context.
%   I_primary = I_secondary x CT_device (matrix sides are secondary amperes;
%   CTs are v2 15000/1600 via the graded matrix). Secondary arithmetic is
%   frozen phase5_ct (the single source of truth; the phase5_ct_table
%   wrapper rejects 1600 by locked guard and frozen files stay untouched).
%   I0_A joins real production Iseq0; LG-exact If/3 only when the join
%   truly lacks I0; LLG-without-Iseq0 -> NaN, never invented.
ml = tocell(Mtrx.fault_location); mt = tocell(Mtrx.fault_type); mc = tocell(Mtrx.caseID);
jl = tocell(TiJ.fault_location); jt = tocell(TiJ.fault_type); jc = tocell(TiJ.caseID);
Jseq = double(TiJ.Iseq0_kA(:)); Jtot = double(TiJ.I_primary_A(:));
oLoc = {}; oTyp = {}; oCase = {}; oDev = {}; oSide = {};
oIp = []; oIk = []; oCt = []; oIs = []; oI0 = []; oSrc = {};
oProv = {}; oScope = {};
PROV = ['SOURCE-BACKED:Phase-4-production-import-branch-through-current-via-frozen-phase5_coord;' ...
    'secondaries-via-frozen-phase5_ct-arithmetic-v2-CTs-15000-gen-1600-GSUT-GIS'];
for i = 1:height(Mtrx)
    j = find(strcmp(jc, mc{i}) & strcmp(jl, ml{i}) & strcmp(jt, mt{i}), 1, 'first');
    if isempty(j)
        error('phase5b_production:join', ...
            'relay-currents join missed %s %s %s.', mc{i}, ml{i}, mt{i});
    end
    if isfinite(Jseq(j))
        i0 = Jseq(j) * 1000;
        src = 'Iseq0-SOURCE-BACKED-Phase-4-production';
    elseif strcmp(mt{i}, 'LG')
        i0 = Jtot(j) / 3;
        src = 'LG-exact-If/3-DERIVED';
    else
        i0 = NaN;
        src = 'MISSING-no-Iseq0-LLG-neutral-counted-once-N/A';
    end
    if isfinite(Mtrx.I_down_A(i)) && isfinite(Mtrx.ct_down(i))
        oLoc{end + 1} = ml{i}; oTyp{end + 1} = mt{i}; oCase{end + 1} = mc{i}; %#ok<AGROW>
        oDev{end + 1} = Mtrx.downstream{i}; oSide{end + 1} = 'downstream'; %#ok<AGROW>
        oIp(end + 1) = Mtrx.I_down_A(i) * Mtrx.ct_down(i); %#ok<AGROW>
        oIk(end + 1) = oIp(end) / 1000; %#ok<AGROW>
        oCt(end + 1) = Mtrx.ct_down(i); %#ok<AGROW>
        oIs(end + 1) = Mtrx.I_down_A(i); %#ok<AGROW>
        oI0(end + 1) = i0; %#ok<AGROW>
        oSrc{end + 1} = src; %#ok<AGROW>
        oProv{end + 1} = PROV; oScope{end + 1} = 'PRIMARY'; %#ok<AGROW>
    end
    if isfinite(Mtrx.I_up_A(i)) && isfinite(Mtrx.ct_up(i))
        oLoc{end + 1} = ml{i}; oTyp{end + 1} = mt{i}; oCase{end + 1} = mc{i}; %#ok<AGROW>
        oDev{end + 1} = Mtrx.upstream{i}; oSide{end + 1} = 'upstream'; %#ok<AGROW>
        oIp(end + 1) = Mtrx.I_up_A(i) * Mtrx.ct_up(i); %#ok<AGROW>
        oIk(end + 1) = oIp(end) / 1000; %#ok<AGROW>
        oCt(end + 1) = Mtrx.ct_up(i); %#ok<AGROW>
        oIs(end + 1) = Mtrx.I_up_A(i); %#ok<AGROW>
        oI0(end + 1) = i0; %#ok<AGROW>
        oSrc{end + 1} = src; %#ok<AGROW>
        oProv{end + 1} = PROV; oScope{end + 1} = 'PRIMARY'; %#ok<AGROW>
    end
end
Trc = table(oLoc', oTyp', oCase', oDev', oSide', oIp', oIk', oCt', ...
    oIs', oI0', oSrc', oProv', oScope', ...
    'VariableNames', {'fault_location', 'fault_type', 'caseID', ...
    'device_id', 'side', 'I_primary_A', 'I_primary_kA', 'CT_ratio', ...
    'I_secondary_A', 'I0_A', 'I0_source', 'provenance', 'scope'});
if height(Trc) < 1
    error('phase5b_production:rows', 'relay-currents table empty (matrix sides all missing).');
end
end

function Dduty = duty_provenance_split(Dduty12)
% DUTY_PROVENANCE_SPLIT  Stamp provenance/scope on the 12-col wrapper output.
%   Q0 rows (NOT DETERMINABLE interrupting): SOURCE-BACKED import basis.
%   52G rows (100 kA documented): SOURCE-BACKED rating basis.
%   NOTE row (ESTIMATED 50 kA station reference): ESTIMATED basis.
vn = Dduty12.Properties.VariableNames;
for k = 1:numel({'location', 'breaker_ref', 'fault_type', 'caseID', 'I_sym_kA', ...
        'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
        'equipment_rating_kA', 'equipment_basis'})
    need = {'location', 'breaker_ref', 'fault_type', 'caseID', 'I_sym_kA', ...
        'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
        'equipment_rating_kA', 'equipment_basis'};
    if ~any(strcmp(vn, need{k}))
        error('phase5b_production:schema', 'phase5b_duty output missing column %s.', need{k});
    end
end
n = height(Dduty12);
prov = cell(n, 1);
for i = 1:n
    br = Dduty12.breaker_ref{i};
    if isstring(br) && isscalar(br), br = char(br); end
    vd = Dduty12.verdict{i};
    if isstring(vd) && isscalar(vd), vd = char(vd); end
    if strcmp(strtrim(vd), 'NOTE')
        prov{i} = ['SOURCE-BACKED:Phase-4-production-import-joined-F3-LLL-total;' ...
            'ESTIMATED:50.00-kA-station-reference-informational-only-never-duty-basis'];
    elseif strcmp(strtrim(br), '52G')
        prov{i} = ['SOURCE-BACKED:Phase-4-production-import-through-current-branch-GEN_Q;' ...
            'SOURCE-BACKED:ledger-GCB-10BAC10-100kA-52G-interrupting-rating'];
    else
        prov{i} = 'SOURCE-BACKED:Phase-4-production-import-through-current-branch';
    end
end
Dduty = Dduty12;
Dduty.provenance = prov;
Dduty.scope = repmat({'PRIMARY'}, n, 1);
Dduty = Dduty(:, {'location', 'breaker_ref', 'fault_type', 'caseID', ...
    'I_sym_kA', 'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
    'equipment_rating_kA', 'equipment_basis', 'provenance', 'scope'});
end

function S = sensitivity_v2(T40, devicesProd, Rreg)
%SENSITIVITY_V2  v2-adapted GEN-scope sensitivity (C11 BLOCKED fallback).
%   The frozen PHASE5_SENSITIVITY is BLOCKED for v2 reuse (never modified):
%   it hard-codes the v1 2000 CT on its upstream GSUT leg
%   (phase5_sensitivity.m:137 'IsUp = pkUp / 2000', :190 'primUp / 2000',
%   :193 reason 'upstream-GSUT-HV-51-2000/1-untouched', comments :9/:11)
%   instead of reading device ct_ratio (1600 in v2). Evidence pinned in
%   test_phase5b_writer. This engine ports the frozen GEN-scope doctrine
%   exactly, reading every pickup/CT/TMS from the v2-resolved devices:
%     GEN-51 (phase, all 40 combos) + GEN-51N (earth, LG/LLG only, 20 rows)
%     = 60 rows; GEN dial fixed from the PRIMARY scheme via the device CT
%     (Is_fixed = P/ct_device, 15000); legacy secondaries via Rreg.ct_legacy
%     (16000 fence, read never hard-coded); upstream GSUT-HV-51 backup via
%     ITS device CT (1600 — the fix) with the v2-resolved pickup/TMS;
%     EF TMS 0.15 from the stamped devices (pickup-resolved, never registry
%     0.20). Frozen phase5_ct + phase5_time + phase5_ct_table(T40,16000)
%     audit reference only (legacy fence unchanged in v2).
%   Relay primaries mirror frozen branch parity: GEN-51 phase -> GEN_Q leg
%   else net total; GEN-51N F1/F2 -> 3xI0 neutral-once else LG-exact If/3
%   else NaN; GEN-51N F3/F4/F5 -> 3x leg_NER_earth delta block else NaN.
%   Verdict doctrine identical to frozen (CTI 0.3 s; NO-TRIP / NO-PAIR /
%   NOT DETERMINABLE FROM AVAILABLE DATA). 28 locked cols, scope
%   SENSITIVITY, provenance LEGACY-tagged + v2-adaptation note.
d51 = finddev(devicesProd, 'GEN-51');
d51N = finddev(devicesProd, 'GEN-51N');
dUp = finddev(devicesProd, 'GSUT-HV-51');
ctGen = read_ct(d51, 'GEN-51');
ctLeg = double(Rreg.ct_legacy);
if ~(isscalar(ctLeg) && isfinite(ctLeg) && ctLeg > 0)
    error('phase5b_production:sensitivity', 'Rreg.ct_legacy must be finite > 0 (16000 fence, read never hard-coded).');
end
ctUp = read_ct(dUp, 'GSUT-HV-51');
pk51 = read_pickup(d51, 'GEN-51');
pkN = read_pickup(d51N, 'GEN-51N');
pkUp = read_pickup(dUp, 'GSUT-HV-51');
[tms51, cv51] = read_tc(d51, 'GEN-51');
[tmsN, cvN] = read_tc(d51N, 'GEN-51N');
[tmsUp, cvUp] = read_tc(dUp, 'GSUT-HV-51');
IsFix51 = pk51 / ctGen;
IsFixN = pkN / ctGen;
IsUp = pkUp / ctUp;
CTI = 0.3;
locs = tocell(T40.fault_location);
typs = tocell(T40.fault_type);
cases = tocell(T40.caseID);
n = height(T40);
If_A = double(T40.I_primary_A(:));
If_kA = double(T40.I_primary_kA(:));
if any(~isfinite(If_A)) || any(~isfinite(If_kA))
    error('phase5b_production:sensitivity', 'T40 fault currents must be finite.');
end
hasIseq0 = any(strcmp(T40.Properties.VariableNames, 'Iseq0_kA'));
if hasIseq0
    Iseq0_kA = double(T40.Iseq0_kA(:));
else
    Iseq0_kA = NaN(n, 1);
end
legGEN = legcol(T40, 'leg_GEN_kA', n);
legHV = legcol(T40, 'leg_GSUT_HV_kA', n);
legNER = legcol(T40, 'leg_NER_earth_kA', n);
Tleg = phase5_ct_table(T40, 16000, 'LEGACY-16000/1');
if height(Tleg) ~= n
    error('phase5b_production:sensitivity', 'legacy audit table row count diverged from T40.');
end
earthMask = strcmp(typs, 'LG') | strcmp(typs, 'LLG');
nEarth = sum(earthMask);
total = n + nEarth;
oLoc = cell(total, 1); oTyp = cell(total, 1); oCase = cell(total, 1);
oDev = cell(total, 1); oPath = cell(total, 1);
oIprim = NaN(total, 1); oIk = NaN(total, 1);
oIsecP = NaN(total, 1); oIsecS = NaN(total, 1);
oCtP = repmat(ctGen, total, 1); oCtL = repmat(ctLeg, total, 1);
oTag = repmat({'LEGACY-16000/1'}, total, 1);
oPk = NaN(total, 1); oTms = NaN(total, 1); oCv = cell(total, 1);
oTp = NaN(total, 1); oTs = NaN(total, 1); oDt = NaN(total, 1);
oDir = cell(total, 1);
oMgP = NaN(total, 1); oMgS = NaN(total, 1); oDmg = NaN(total, 1);
oMdir = cell(total, 1);
oVp = cell(total, 1); oVs = cell(total, 1);
oScope = repmat({'SENSITIVITY'}, total, 1);
oProv = repmat({['LEGACY:CT-16000/1-fenced-sensitivity-vs-PRIMARY-15000/1-GEN-v2-adapted-' ...
    'upstream-1600/1-device-CT-SOURCE-BACKED-Phase-4-import']}, total, 1);
oReason = cell(total, 1);
j = 0;
for i = 1:n
    loc = locs{i};
    typ = typs{i};
    cs = cases{i};
    isGenZone = strcmp(loc, 'F1') || strcmp(loc, 'F2');
    if isfinite(legGEN(i)) && legGEN(i) >= 0
        prim51 = legGEN(i) * 1000;
        path51 = 'GEN_Q-branch-leg_GEN_kA-SOURCE-BACKED';
    else
        prim51 = If_A(i);
        path51 = 'net-total-fallback-no-leg-join';
    end
    secP51 = phase5_ct(prim51, ctGen).Isec_A;
    secS51 = phase5_ct(prim51, ctLeg).Isec_A;
    tP51 = sidetime(secP51, IsFix51, tms51, cv51);
    tS51 = sidetime(secS51, IsFix51, tms51, cv51);
    if isGenZone
        if isfinite(legHV(i)) && legHV(i) >= 0
            primUp = legHV(i) * 1000;
            upTag = 'GSUT_HV-branch-leg_GSUT_HV_kA-SOURCE-BACKED';
        else
            primUp = If_A(i);
            upTag = 'net-total-fallback-no-leg-join';
        end
        tUp = sidetime(primUp / ctUp, IsUp, tmsUp, cvUp);
        [mgP, vP] = pairverdict(tP51, tUp, CTI);
        [mgS, vS] = pairverdict(tS51, tUp, CTI);
        mgNote = sprintf([';upstream-GSUT-HV-51-v2-device-CT-%.0f/1(t_up=%.3fs;%s);' ...
            'CTI-0.3s-study-threshold'], ctUp, tUp, upTag);
    else
        tUp = NaN;
        [mgP, vP] = nopairverdict(tP51);
        [mgS, vS] = nopairverdict(tS51);
        mgNote = [';NO-PAIR (topology): GEN backup not in grid-zone chain;' ...
            'backup-t_down-reported-no-margin-asserted'];
    end
    [dt51, dir51] = classdir(tP51, tS51);
    [dmg51, mdir51] = classmargin(mgP, mgS);
    j = j + 1;
    oLoc{j} = loc; oTyp{j} = typ; oCase{j} = cs; oDev{j} = 'GEN-51';
    oPath{j} = path51; oIprim(j) = prim51; oIk(j) = prim51 / 1000;
    oIsecP(j) = secP51; oIsecS(j) = secS51;
    oPk(j) = pk51; oTms(j) = tms51; oCv{j} = cv51;
    oTp(j) = tP51; oTs(j) = tS51; oDt(j) = dt51; oDir{j} = dir51;
    oMgP(j) = mgP; oMgS(j) = mgS; oDmg(j) = dmg51; oMdir{j} = mdir51;
    oVp{j} = vP; oVs{j} = vS;
    oReason{j} = sprintf(['GEN-51 %s %s %s: relay-primary %.6g A (%s);' ...
        'pickup %.2f A-primary dial-fixed %.6g A-sec via device CT %.0f/1;' ...
        'TMS %.3g %s;t_prim %.3fs t_sens %.3fs dt %.3fs (%s)%s;' ...
        'LEGACY-16000/1 fenced vs PRIMARY-15000/1 GEN (v2-adapted upstream %.0f/1)'], ...
        loc, typ, cs, prim51, path51, pk51, IsFix51, ctGen, ...
        tms51, cv51, tP51, tS51, dt51, dir51, mgNote, ctUp);
    if strcmp(typ, 'LG') || strcmp(typ, 'LLG')
        if isGenZone
            if isfinite(Iseq0_kA(i))
                primN = 3 * Iseq0_kA(i) * 1000;
                pathN = '3I0-fault-total-Iseq0-SOURCE-BACKED-neutral-counted-once';
                missN = false;
            elseif strcmp(typ, 'LG')
                primN = If_A(i);
                pathN = '3I0-LG-exact-If-over-3-DERIVED-neutral-counted-once';
                missN = false;
            else
                primN = NaN;
                pathN = 'MISSING-no-Iseq0-LLG-neutral-counted-once-N/A';
                missN = true;
            end
        else
            if isfinite(legNER(i)) && legNER(i) >= 0
                primN = 3 * legNER(i) * 1000;
                pathN = '3xleg_NER_earth-delta-block-neutral-counted-once';
                missN = false;
            else
                primN = NaN;
                pathN = '3xleg_NER_earth-MISSING-neutral-counted-once-N/A';
                missN = true;
            end
        end
        if isfinite(primN) && primN >= 0
            secPN = phase5_ct(primN, ctGen).Isec_A;
            secSN = phase5_ct(primN, ctLeg).Isec_A;
            tPN = sidetime(secPN, IsFixN, tmsN, cvN);
            tSN = sidetime(secSN, IsFixN, tmsN, cvN);
        else
            secPN = NaN;
            secSN = NaN;
            tPN = NaN;
            tSN = NaN;
        end
        [vPN, vSN, eNote] = earthverdicts(tPN, tSN, missN, isGenZone, loc, typ, cs);
        [dtN, dirN] = classdir(tPN, tSN);
        j = j + 1;
        oLoc{j} = loc; oTyp{j} = typ; oCase{j} = cs; oDev{j} = 'GEN-51N';
        oPath{j} = pathN; oIprim(j) = primN; oIk(j) = primN / 1000;
        oIsecP(j) = secPN; oIsecS(j) = secSN;
        oPk(j) = pkN; oTms(j) = tmsN; oCv{j} = cvN;
        oTp(j) = tPN; oTs(j) = tSN; oDt(j) = dtN; oDir{j} = dirN;
        oMgP(j) = NaN; oMgS(j) = NaN; oDmg(j) = NaN; oMdir{j} = 'N/A';
        oVp{j} = vPN; oVs{j} = vSN;
        oReason{j} = sprintf(['GEN-51N %s %s %s: relay-primary %.6g A (%s);' ...
            'pickup %.2f A-primary dial-fixed %.6g A-sec via device CT %.0f/1;' ...
            'TMS %.3g %s (EF pickup-resolved);t_prim %.3fs t_sens %.3fs dt %.3fs (%s);%s;' ...
            'LEGACY-16000/1 fenced vs PRIMARY-15000/1 GEN'], ...
            loc, typ, cs, primN, pathN, pkN, IsFixN, ctGen, ...
            tmsN, cvN, tPN, tSN, dtN, dirN, eNote);
    end
end
S = table(oLoc, oTyp, oCase, oDev, oIprim, oIk, oPath, oIsecP, oIsecS, ...
    oCtP, oCtL, oTag, oPk, oTms, oCv, oTp, oTs, oDt, oDir, ...
    oMgP, oMgS, oDmg, oMdir, oVp, oVs, oScope, oProv, oReason, ...
    'VariableNames', {'fault_location', 'fault_type', 'caseID', 'device_id', ...
    'I_primary_A', 'I_primary_kA', 'relay_path', 'I_sec_primary_A', ...
    'I_sec_sens_A', 'ct_primary', 'ct_legacy', 'ct_tag', 'pickup_primary_A', ...
    'tms', 'curve', 't_primary_s', 't_sens_s', 'dt_s', 'direction', ...
    'margin_primary_s', 'margin_sens_s', 'dmargin_s', 'margin_direction', ...
    'verdict_primary', 'verdict_sens', 'scope', 'provenance', 'reason'});
end

function d = finddev(devices, id)
d = [];
for k = 1:numel(devices)
    did = devices(k).device_id;
    if isstring(did) && isscalar(did), did = char(did); end
    if ischar(did) && strcmp(strtrim(did), id), d = devices(k); return; end
end
error('phase5b_production:devices', 'device %s not found in v2 devices.', id);
end

function ct = read_ct(d, id)
ct = double(d.ct_ratio);
if ~(isscalar(ct) && isfinite(ct) && ct > 0)
    error('phase5b_production:sensitivity', 'device %s needs finite ct_ratio > 0 (v2 device CT, read never hard-coded).', id);
end
end

function pk = read_pickup(d, id)
pk = double(d.pickup_A);
if ~(isscalar(pk) && isfinite(pk) && pk > 0)
    error('phase5b_production:sensitivity', 'device %s needs finite stamped pickup_A > 0 (C4-resolved, read never hard-coded).', id);
end
end

function [tms, cv] = read_tc(d, id)
tm = double(d.tms);
if ~(isscalar(tm) && isfinite(tm) && tm > 0)
    error('phase5b_production:sensitivity', 'device %s needs finite stamped tms > 0 (C4-resolved, read never hard-coded).', id);
end
tms = tm;
cv = d.curve;
if isstring(cv) && isscalar(cv), cv = char(cv); end
if ischar(cv) && ~isempty(strtrim(cv))
    cv = upper(strtrim(cv));
else
    cv = 'SI';
end
end

function t = sidetime(Isec, IsSec, tms, cv)
if ~isscalar(Isec) || ~isreal(Isec) || ~isfinite(Isec) || Isec < 0
    t = NaN;
    return;
end
t = phase5_time(Isec, IsSec, tms, cv);
end

function [mg, vd] = pairverdict(tDown, tUp, CTI)
if ~isfinite(tDown) || ~isfinite(tUp)
    mg = NaN;
    vd = 'NO-TRIP';
    return;
end
mg = tUp - tDown;
if mg >= CTI
    vd = 'PASS';
else
    vd = 'FAIL';
end
end

function [mg, vd] = nopairverdict(tDown)
mg = NaN;
if ~isfinite(tDown)
    vd = 'NO-TRIP';
else
    vd = 'NO-PAIR';
end
end

function [vP, vS, note] = earthverdicts(tP, tS, missN, isGenZone, loc, typ, cs)
if missN
    if isGenZone
        vP = 'NO-TRIP';
        vS = 'NO-TRIP';
        note = sprintf(['NO-TRIP: relay current NOT DETERMINABLE (I0 missing for %s %s %s;' ...
            ' NOT DETERMINABLE FROM AVAILABLE DATA detail)-never-forced-PASS;' ...
            'upstream earth element has no residual CT'], loc, typ, cs);
    else
        vP = 'NOT DETERMINABLE FROM AVAILABLE DATA';
        vS = 'NOT DETERMINABLE FROM AVAILABLE DATA';
        note = sprintf(['NOT DETERMINABLE FROM AVAILABLE DATA: NER leg missing for %s %s %s;' ...
            ' generator earth current cannot be determined, never invented'], loc, typ, cs);
    end
    return;
end
if isfinite(tP)
    vP = 'NOT DETERMINABLE FROM AVAILABLE DATA';
else
    vP = 'NO-TRIP';
end
if isfinite(tS)
    vS = 'NOT DETERMINABLE FROM AVAILABLE DATA';
else
    vS = 'NO-TRIP';
end
if strcmp(vP, 'NOT DETERMINABLE FROM AVAILABLE DATA') || strcmp(vS, 'NOT DETERMINABLE FROM AVAILABLE DATA')
    note = ['NOT DETERMINABLE FROM AVAILABLE DATA: upstream earth element has no residual CT;' ...
        ' downstream 3I0 trip cannot assert backup coordination, never invented'];
else
    note = ['NO-TRIP: downstream below pickup (HV-fault earth delta block or light earth)' ...
        ' - never-forced-PASS'];
end
end

function [dt, dir] = classdir(tP, tS)
if isnan(tP) && isnan(tS)
    dt = NaN;
    dir = 'NOT-DETERMINABLE';
elseif isnan(tP) || isnan(tS)
    dt = NaN;
    dir = 'NOT-DETERMINABLE';
elseif isinf(tP) && isinf(tS)
    dt = 0;
    dir = 'unchanged-no-trip';
elseif isfinite(tP) && isinf(tS)
    dt = Inf;
    dir = 'slower-no-trip';
elseif isinf(tP) && isfinite(tS)
    dt = -Inf;
    dir = 'faster-trip';
else
    dt = tS - tP;
    if abs(dt) <= 1e-9
        dir = 'unchanged';
    elseif dt > 0
        dir = 'slower';
    else
        dir = 'faster';
    end
end
end

function [dmg, mdir] = classmargin(mgP, mgS)
if isfinite(mgP) && isfinite(mgS)
    dmg = mgS - mgP;
    if abs(dmg) <= 1e-9
        mdir = 'unchanged';
    elseif dmg < 0
        mdir = 'tighter';
    else
        mdir = 'wider';
    end
else
    dmg = NaN;
    mdir = 'N/A';
end
end

function v = legcol(Tsec, name, n)
%LEGCOL  Branch-leg column (kA) or NaN vector when absent.
if any(strcmp(Tsec.Properties.VariableNames, name))
    v = double(Tsec.(name)(:));
    if numel(v) ~= n, v = NaN(n, 1); end
else
    v = NaN(n, 1);
end
end

function c = tocell(v)
%TOCELL  Normalize table/struct text to cellstr.
if iscell(v)
    c = v(:);
    for k = 1:numel(c)
        if isstring(c{k}) && isscalar(c{k}), c{k} = char(c{k}); end
    end
elseif isstring(v)
    c = cellstr(v(:));
elseif ischar(v)
    c = cellstr(v);
else
    error('phase5b_production:schema', 'text column must be cell/string/char.');
end
end

function hex = sha256file(path)
%SHA256FILE  SHA-256 hex digest via Java MessageDigest (no toolbox).
md = java.security.MessageDigest.getInstance('SHA-256');
jpath = java.io.File(path).toPath();
md.update(java.nio.file.Files.readAllBytes(jpath));
dig = md.digest();
bi = java.math.BigInteger(1, dig);
hex = char(bi.toString(16));
hex = [repmat('0', 1, 64 - numel(hex)) hex];
end

function [NP, NF] = run_phase5b_tests(varargin)
%RUN_PHASE5B_TESTS  Phase-5b test runner (Phase-5b Task C12).
%   [NP, NF] = RUN_PHASE5B_TESTS() runs every matlab/tests/test_phase5b_*.m
%   suite (discovered via the test_phase5b_ledger anchor on the path, so gap
%   suites are picked up without runner edits) plus the 14-leg
%   phase5b_validate() engine (R0 Phase-4 regression + B01..B13), accumulates
%   passed/failed counts (each validation leg counts one check), and prints
%   'phase5b_tests: NP passed, NF failed'.
%   A suite that errors counts one failure and the runner continues, so one
%   broken suite never hides the rest; the error text stays loud.
%   The frozen v1 runner is never called or modified (see plan global
%   constraints).
%   All errors raised here are 'phase5b'-prefixed.
if nargin ~= 0
    error('phase5b_tests:args', 'usage: [NP, NF] = run_phase5b_tests().');
end
anchor = which('test_phase5b_ledger');
if isempty(anchor)
    error('phase5b_tests:path', 'test_phase5b_ledger not on path (run with addpath(genpath(''matlab''))).');
end
tdir = fileparts(anchor);
list = dir(fullfile(tdir, 'test_phase5b_*.m'));
NP = 0; NF = 0;
for k = 1:numel(list)
    [~, name] = fileparts(list(k).name);
    try
        [np, nf] = feval(name);
        NP = NP + np; NF = NF + nf;
    catch ME
        NF = NF + 1;
        fprintf('  ERROR %s: %s (%s)\n', name, ME.message, ME.identifier);
    end
end
try
    V = phase5b_validate();
    for k = 1:numel(V.legs)
        if V.legs(k).pass
            NP = NP + 1;
        else
            NF = NF + 1;
        end
        if V.legs(k).pass
            st = 'PASS';
        else
            st = 'FAIL';
        end
        fprintf('  %s %s residual=%.6g note=%s\n', st, V.legs(k).id, V.legs(k).residual, V.legs(k).note);
    end
catch ME
    NF = NF + 1;
    fprintf('  ERROR phase5b_validate: %s (%s)\n', ME.message, ME.identifier);
end
fprintf('phase5b_tests: %d passed, %d failed\n', NP, NF);
end

function G = phase5b_gate(ov)
%PHASE5B_GATE  Phase-5b extended quality-gate predicate runner (Phase-5b Task C14).
%   G = PHASE5B_GATE() is a read-only consumer of
%   results/phase5_protection_v2/ + PHASE5_FINAL_REPORT.md (rewritten v2 body
%   + section 20 v1 appendix) + results/phase5_protection/ (v1 untouched
%   spot-check only) + results/phase4_fault/production/ (it modifies
%   nothing): it evaluates 23 predicates (v1 P01-P17 re-pointed at v2
%   outputs + B01-B06 physical predicates), prints a checklist, and errors
%   error('phase5b_gate:fail') when any predicate fails.
%
%   G = PHASE5B_GATE(ov) accepts an optional struct overriding shipped inputs
%   in-memory only (negative-path injection for tests); recognised fields:
%   faultInputs, relayCurrents, coordMatrix, coordMargins, duty,
%   sensitivity, settings, registry, validation, effectiveness (MATLAB
%   tables), reportText (char), noThrow (logical: return G without erroring).
%
%   G fields: .n (23), .ids (23 cellstr slugs), .pass (23 logical),
%   .note (23 cellstr), .npass (scalar count).
%
%   The 23 predicates (v1 P01-P17 re-pointed at v2 + B01-B06):
%     P01 regression        R0 identities: F3 LLL OUT 50.5308851865359 kA
%                           (1e-6), F1 LG OUT 0.00727200442799167 kA (1e-9).
%     P02 cases             exactly {LF360_GAT_OUT, LF360_GAT_IN}.
%     P03 locs              exactly {F1..F5}.
%     P04 types             exactly {LLL,LG,LL,LLG}.
%     P05 ct-conversions    per-row Isec == Iprim./CT_ratio (tol 1e-9 abs).
%     P06 relay-calcs       v2 settings anchors (GEN-51 17170.8, GEN-51N 5,
%                           GSUT-HV-51 1380, GIS-Q0-51 1043.94798235109) +
%                           GEN-51N F1 LG operating-time recomputation via
%                           phase5_time (TMS 0.15 EF) matches matrix t_down
%                           (tol 1e-9).
%     P07 matrix-complete   coordination matrix + margins 96 rows each.
%     P08 margins-numeric   finite rows margin == t_up-t_down (1e-9);
%                           non-finite rows margin NaN; margins file matches
%                           matrix margins multiset + verdict distribution.
%     P09 duty-separated    no t_up/t_down/margin columns in duty CSV.
%     P10 rating-provenance v2 duty 81 rows: 40 Q0 NOT DETERMINABLE (rating
%                           NaN + equipment 50 WITHSTAND + MISSING basis,
%                           never PASS/FAIL) + 40 52G PASS (rating 100 +
%                           equipment NaN MISSING) + one 50-kA NOTE row
%                           (+1.06%, ESTIMATED, never verdict).
%     P11 assumption-tags   every one of the 9 v1-parity CSVs carries
%                           non-empty provenance + scope on every row;
%                           effectiveness carries non-empty ct_source +
%                           setting_source on every row.
%     P12 legacy-fenced     '16000' appears only in sensitivity CSV raw text.
%     P13 no-scratch        zero case-insensitive 'scratch' hits in 10 CSVs.
%     P14 manifest-hashes   recompute sha256 of the 12 sha256.txt lines.
%     P15 report-match      CSV-derived spots found in report: v2 GIS pickup
%                           exact string, 'FAIL = <n>', 'PASS = <n>',
%                           52G PASS=40 line, effectiveness 48-row 24/24 line
%                           (report-vs-CSV ONLY, never vs test literals).
%     P16 no-IEC-claim      zero case-insensitive 'iec' in duty table; zero
%                           affirmative compliance-claim patterns in report
%                           (case-insensitive both sides; v1 gate limitation
%                           fixed here and recorded).
%     P17 no-Phase3/4-change PHASE3_FINAL_REPORT.md 45504 bytes + production
%                           sha256.txt 7/7 recompute-verify.
%     B01 registry-physical 33-row registry (7 STUDY + 26 PHYSICAL);
%                           GEN-51-SIEMENS-BL + GEN-52G present.
%     B02 no-2000           '2000/1' absent in all 10 v2 CSV raws + no
%                           ct_ratio == 2000 in registry/settings/currents/
%                           matrix CT columns (rated_A 2000 equipment values
%                           are legal and never counted here).
%     B03 dt-flagged        baseline DT-?? flagged: settings BL curve DT-??
%                           + ?? in basis/validation + NaN tms +
%                           USER_ASSERTED provenance; registry BL DT-??; all
%                           SIEMENS-baseline effectiveness backup_time_s NaN
%                           with ?? reason.
%     B04 effectiveness     48 rows ASSERTABLE-DETECT 24 / NOT-DETERMINABLE
%                           24 + report 48-row line.
%     B05 duty-52G          81 rows; 40 52G PASS vs 100 kA (F1 LLL 55.0487
%                           PASS) + report 52G line.
%     B06 v1-untouched      v1 results/phase5_protection/sha256.txt 11/11
%                           recompute-verify (read-only spot-check; v1 dir
%                           never modified).
%
%   CSV readers use readtable(fp,'Delimiter',',') (RFC-4180 quoted-comma
%   dialect). All errors are 'phase5b'-prefixed.
if nargin < 1 || isempty(ov)
    ov = struct();
end
if ~isstruct(ov) || ~isscalar(ov)
    error('phase5b_gate:args', 'ov must be a scalar struct (or omitted).');
end
noThrow = isfield(ov, 'noThrow') && isequal(ov.noThrow, true);
root = ashuganj_root();
outDir = fullfile(root, 'results', 'phase5_protection_v2');
v1Dir = fullfile(root, 'results', 'phase5_protection');
prodDir = fullfile(root, 'results', 'phase4_fault', 'production');

files10 = {'phase5_device_registry.csv', 'phase5_relay_settings.csv', ...
    'phase5_fault_inputs.csv', 'phase5_relay_currents.csv', ...
    'phase5_coordination_matrix.csv', 'phase5_coordination_margins.csv', ...
    'phase5_breaker_duty.csv', 'phase5_sensitivity.csv', ...
    'phase5_validation.csv', 'phase5b_effectiveness.csv'};
FI = getTab(ov, 'faultInputs', outDir, files10{3});
RC = getTab(ov, 'relayCurrents', outDir, files10{4});
MX = getTab(ov, 'coordMatrix', outDir, files10{5});
