[pass(12), note{12}] = pLegacy(raws, files10);
[pass(13), note{13}] = pScratch(raws);
[pass(14), note{14}] = pHashes(outDir);
[pass(15), note{15}] = pReport(ST, MX, DU, EF, rep);
