% =====================================================================
function T = getTab(ov, field, outDir, file)
if isfield(ov, field)
    T = ov.(field);
    if ~istable(T)
        error('phase5b_gate:args', 'ov.%s must be a table.', field);
    end
    return;
end
p = fullfile(outDir, file);
if exist(p, 'file') ~= 2
    error('phase5b_gate:missing', 'output CSV missing: %s', p);
end
T = readtable(p, 'Delimiter', ',');
end

function c = tcell(v)
if iscell(v)
    c = v(:);
elseif isstring(v)
    c = cellstr(v(:));
elseif ischar(v)
    c = cellstr(v);
else
    error('phase5b_gate:schema', 'text column must be cell/string/char.');
end
end

function [p, n] = pRegression(FI)
locs = tcell(FI.fault_location); typs = tcell(FI.fault_type); cs = tcell(FI.caseID);
a = FI(strcmp(locs, 'F3') & strcmp(typs, 'LLL') & strcmp(cs, 'LF360_GAT_OUT'), :);
g = FI(strcmp(locs, 'F1') & strcmp(typs, 'LG') & strcmp(cs, 'LF360_GAT_OUT'), :);
if height(a) ~= 1 || height(g) ~= 1
    p = false; n = 'F3-LLL-OUT / F1-LG-OUT rows not unique-present'; return;
end
d1 = abs(a.I_primary_kA - 50.5308851865359);
d2 = abs(g.I_primary_kA - 0.00727200442799167);
p = (d1 < 1e-6) && (d2 < 1e-9);
n = sprintf('F3-LLL-OUT %.10f kA (d %.2g, tol 1e-6); F1-LG-OUT %.14f kA (d %.2g, tol 1e-9)', ...
    a.I_primary_kA, d1, g.I_primary_kA, d2);
end

function [p, n] = pCases(FI)
u = sort(tcell(unique(tcell(FI.caseID))));
p = isequal(u, {'LF360_GAT_IN'; 'LF360_GAT_OUT'});
n = sprintf('cases {%s}', strjoin(u', ', '));
end

function [p, n] = pLocs(FI)
u = sort(tcell(unique(tcell(FI.fault_location))));
p = isequal(u, {'F1'; 'F2'; 'F3'; 'F4'; 'F5'});
n = sprintf('locs {%s}', strjoin(u', ', '));
end

function [p, n] = pTypes(FI)
u = sort(tcell(unique(tcell(FI.fault_type))));
p = isequal(u, {'LG'; 'LL'; 'LLG'; 'LLL'});
n = sprintf('types {%s}', strjoin(u', ', '));
end

function [p, n] = pCT(RC)
if ~all(isfinite(double(RC.CT_ratio)) & double(RC.CT_ratio) > 0)
    p = false; n = 'non-finite/non-positive CT_ratio present'; return;
end
dev = max(abs(double(RC.I_secondary_A) - double(RC.I_primary_A) ./ double(RC.CT_ratio)));
p = dev <= 1e-9;
n = sprintf('%d rows Isec==Iprim/CT max-dev %.3g (tol 1e-9)', height(RC), dev);
end

function [p, n] = pRelay(ST, RC, MX)
ids = tcell(ST.device_id);
r51 = ST(strcmp(ids, 'GEN-51'), :);
r51N = ST(strcmp(ids, 'GEN-51N'), :);
rGS = ST(strcmp(ids, 'GSUT-HV-51'), :);
rQ0 = ST(strcmp(ids, 'GIS-Q0-51'), :);
if height(r51) ~= 1 || height(r51N) ~= 1 || height(rGS) ~= 1 || height(rQ0) ~= 1
    p = false; n = 'settings device rows not unique-present'; return;
end
c1 = abs(r51.setting_A_primary - 17170.8);
c2 = abs(r51N.setting_A_primary - 5);
c3 = abs(rGS.setting_A_primary - 1380);
c4 = abs(rQ0.setting_A_primary - 1043.94798235109);
locs = tcell(RC.fault_location); typs = tcell(RC.fault_type);
cs = tcell(RC.caseID); dv = tcell(RC.device_id);
rr = RC(strcmp(locs, 'F1') & strcmp(typs, 'LG') & strcmp(cs, 'LF360_GAT_OUT') ...
    & strcmp(dv, 'GEN-51N'), :);
if height(rr) ~= 1
    p = false; n = 'GEN-51N F1-LG-OUT relay-current row not unique'; return;
end
cv = tcell(r51N.curve); tms = double(r51N.tms);
t = phase5_time(double(rr.I_secondary_A), double(r51N.setting_A_primary) ...
    / double(r51N.ct_ratio), tms, char(cv{1}));
ml = tcell(MX.fault_location); mt = tcell(MX.fault_type);
mc = tcell(MX.caseID); md = tcell(MX.downstream);
mr = MX(strcmp(ml, 'F1') & strcmp(mt, 'LG') & strcmp(mc, 'LF360_GAT_OUT') ...
    & strcmp(md, 'GEN-51N'), :);
if height(mr) ~= 1
    p = false; n = 'GEN-51N F1-LG-OUT matrix row not unique'; return;
end
c5 = abs(t - double(mr.t_down_s));
p = (c1 < 1e-6) && (c2 < 1e-12) && (c3 < 1e-9) && (c4 < 1e-6) && (c5 < 1e-9);
n = sprintf(['GEN-51 %.2f (d %.2g); GEN-51N %.4f; GSUT %.2f; GIS-Q0 %.8f; ' ...
    'EF t recompute %.8f s vs matrix %.8f s (d %.2g)'], ...
    r51.setting_A_primary, c1, r51N.setting_A_primary, ...
    rGS.setting_A_primary, rQ0.setting_A_primary, t, double(mr.t_down_s), c5);
end

function [p, n] = pMatrix(MX, MG)
p = (height(MX) == 96) && (height(MG) == 96);
n = sprintf('coordination_matrix %d rows; coordination_margins %d rows (expect 96/96)', ...
    height(MX), height(MG));
end

function [p, n] = pMargins(MX, MG)
fin = isfinite(double(MX.t_down_s)) & isfinite(double(MX.t_up_s));
d = abs(double(MX.margin_s(fin)) - (double(MX.t_up_s(fin)) - double(MX.t_down_s(fin))));
okFin = all(d < 1e-9);
okNaN = all(isnan(double(MX.margin_s(~fin))));
a = sort(double(MX.margin_s)); b = sort(double(MG.margin_s));
okSet = isequal(isnan(a), isnan(b)) ...
    && all(abs(a(~isnan(a)) - b(~isnan(b))) < 1e-12);
[ua, ~, ia] = unique(tcell(MX.verdict)); ca = accumarray(ia, 1);
[ub, ~, ib] = unique(tcell(MG.verdict)); cb = accumarray(ib, 1);
okV = isequal(sortrows([ua num2cell(ca)]), sortrows([ub num2cell(cb)]));
p = okFin && okNaN && okSet && okV;
n = sprintf(['finite %d max-dev %.3g; non-finite %d all-NaN %d; ' ...
    'margins-file multiset %d; verdict-dist %d'], ...
    sum(fin), max([d; 0]), sum(~fin), okNaN, okSet, okV);
end

function [p, n] = pDutySep(DU)
vn = DU.Properties.VariableNames;
bad = {};
for k = 1:numel(vn)
    v = vn{k};
    if ~isempty(strfind(v, 'margin')) || ~isempty(strfind(v, 't_up')) ...
            || ~isempty(strfind(v, 't_down'))
        bad{end + 1} = v; %#ok<AGROW>
    end
end
p = isempty(bad);
if p
    n = sprintf('duty %d cols; no time/margin columns', numel(vn));
else
    n = sprintf('forbidden duty columns: %s', strjoin(bad, ', '));
end
end

function [p, n] = pRating(DU, FI)
isNote = strcmp(tcell(DU.verdict), 'NOTE');
isQ0det = strcmp(tcell(DU.breaker_ref), 'Q0') & strcmp(tcell(DU.verdict), 'NOT DETERMINABLE FROM AVAILABLE DATA');
is52 = strcmp(tcell(DU.breaker_ref), '52G') & strcmp(tcell(DU.verdict), 'PASS');
Dq = DU(isQ0det, :);
Dg = DU(is52, :);
Dn = DU(isNote, :);
honestQ = (sum(isQ0det) == 40) && all(isnan(double(Dq.rating_kA))) ...
    && all(abs(double(Dq.equipment_rating_kA) - 50) < 1e-12) ...
    && ~any(strcmp(tcell(Dq.verdict), 'PASS')) ...
    && ~any(strcmp(tcell(Dq.verdict), 'FAIL'));
miss = true;
bs = tcell(Dq.basis);
for k = 1:numel(bs)
    if isempty(strfind(bs{k}, 'MISSING')), miss = false; break; end
end
honestG = (sum(is52) == 40) && all(abs(double(Dg.rating_kA) - 100) < 1e-12) ...
    && all(isnan(double(Dg.equipment_rating_kA)));
locs = tcell(FI.fault_location); typs = tcell(FI.fault_type); cs = tcell(FI.caseID);
f3 = FI(strcmp(locs, 'F3') & strcmp(typs, 'LLL') & strcmp(cs, 'LF360_GAT_OUT'), :);
oneNote = (sum(isNote) == 1) && (height(f3) == 1) ...
    && (abs(double(Dn.I_sym_kA) - double(f3.I_primary_kA)) < 1e-6) ...
    && (abs(double(Dn.rating_kA) - 50.0) < 1e-12) ...
    && (abs(double(Dn.equipment_rating_kA) - 50.0) < 1e-12) ...
    && ~isempty(strfind(Dn.note{1}, '+1.06%')) ...
    && ~isempty(strfind(lower(Dn.basis{1}), 'estimat')) ...
    && strcmp(Dn.verdict{1}, 'NOTE');
dom = all(strcmp(tcell(DU.breaker_ref), 'Q0') | strcmp(tcell(DU.breaker_ref), '52G'));
p = honestQ && miss && honestG && oneNote && dom && (height(DU) == 81);
n = sprintf(['duty 81 rows: 40 Q0 NOT-DET/NaN-rating/50-WITHSTAND %d; ' ...
    '40 52G PASS/100-kA %d; one NOTE %.4f kA +1.06%% ESTIMATED %d'], ...
    honestQ && miss, honestG, double(Dn.I_sym_kA), oneNote);
end

function [p, n] = pTags(tabs9, files9, EF)
bad = 0;
for k = 1:9
    T = tabs9{k};
    vn = T.Properties.VariableNames;
    if ~any(strcmp(vn, 'provenance')) || ~any(strcmp(vn, 'scope'))
        bad = bad + 1; continue;
    end
    if ~colFull(T.provenance) || ~colFull(T.scope)
        bad = bad + 1;
    end
end
effOK = false;
effNote = '';
if istable(EF)
    vn = EF.Properties.VariableNames;
    if any(strcmp(vn, 'ct_source')) && any(strcmp(vn, 'setting_source'))
        effOK = colFull(EF.ct_source) && colFull(EF.setting_source);
        if effOK
            effNote = 'effectiveness ct/setting sources non-empty';
        else
            effNote = 'effectiveness ct/setting sources have empties';
        end
    else
        effNote = 'effectiveness missing ct_source/setting_source';
    end
else
    effNote = 'effectiveness table missing';
end
p = (bad == 0) && effOK;
n = sprintf('provenance+scope non-empty on 9 CSVs (tables failing: %d); %s', bad, effNote);
end

function ok = colFull(v)
ok = true;
if iscell(v)
    for i = 1:numel(v)
        vv = v{i};
        if isstring(vv) && isscalar(vv), vv = char(vv); end
        if ~ischar(vv) || isempty(strtrim(vv)), ok = false; return; end
    end
elseif isstring(v)
    for i = 1:numel(v)
        if strlength(strtrim(v(i))) == 0, ok = false; return; end
    end
elseif ischar(v)
    if isempty(strtrim(v)), ok = false; end
else
    ok = false;
end
end

function [p, n] = pLegacy(raws, files10)
hit = false(1, 10);
for k = 1:10
    hit(k) = ~isempty(strfind(raws{k}, '16000'));
end
idx = find(hit, 1);
p = (sum(hit) == 1) && ~isempty(idx) && ~isempty(strfind(files10{idx}, 'sensitivity'));
n = sprintf('''16000'' in %d/10 CSVs (%s)', sum(hit), strjoin(files10(hit), ', '));
if isempty(strjoin(files10(hit), ', '))
    n = '''16000'' in 0/10 CSVs (expect sensitivity only)';
end
end

function [p, n] = pScratch(raws)
h = 0;
for k = 1:10
    h = h + numel(strfind(lower(raws{k}), 'scratch'));
end
p = (h == 0);
n = sprintf('case-insensitive ''scratch'' hits in 10 CSVs: %d', h);
end

function [p, n] = pHashes(outDir)
sp = fullfile(outDir, 'sha256.txt');
if exist(sp, 'file') ~= 2
    error('phase5b_gate:missing', 'sha256.txt missing: %s', sp);
end
lines = strsplit(strtrim(fileread(sp)), char(10));
lines = lines(~cellfun(@isempty, strtrim(lines)));
if numel(lines) ~= 12
    p = false; n = sprintf('sha256.txt has %d lines (expect 12)', numel(lines)); return;
end
bad = 0;
for k = 1:numel(lines)
    ln = strtrim(lines{k});
    sp1 = strfind(ln, ' ');
    if isempty(sp1)
        bad = bad + 1; continue;
    end
    expH = ln(1:sp1(1) - 1);
    fname = strtrim(ln(sp1(end) + 1:end));
    fp = fullfile(outDir, fname);
    if exist(fp, 'file') ~= 2
        bad = bad + 1; continue;
    end
    if ~strcmp(sha256file(fp), lower(expH))
        bad = bad + 1;
    end
end
p = (bad == 0);
n = sprintf('sha256 recompute-verify 12/12 lines (mismatches: %d)', bad);
end

function [p, n] = pReport(ST, MX, DU, EF, rep)
ids = tcell(ST.device_id);
rQ0 = ST(strcmp(ids, 'GIS-Q0-51'), :);
if height(rQ0) ~= 1
    p = false; n = 'GIS-Q0-51 settings row not unique'; return;
end
sPick = sprintf('%.11f', double(rQ0.setting_A_primary));
c1 = ~isempty(strfind(rep, sPick));
if ~c1
    sPick6 = sprintf('%.6f', double(rQ0.setting_A_primary));
    c1 = ~isempty(strfind(rep, sPick6)) && ~isempty(strfind(rep, '1043.94798235109'));
end
nFail = sum(strcmp(tcell(MX.verdict), 'FAIL'));
sF = sprintf('FAIL = %d', nFail);
c2 = ~isempty(strfind(rep, sF));
nPass = sum(strcmp(tcell(MX.verdict), 'PASS'));
sP = sprintf('PASS = %d', nPass);
c3 = ~isempty(strfind(rep, sP));
n52 = sum(strcmp(tcell(DU.breaker_ref), '52G') & strcmp(tcell(DU.verdict), 'PASS'));
s52a = sprintf('%d x 52G PASS', n52);
s52b = sprintf('52G PASS = %d', n52);
c4 = ~isempty(strfind(rep, s52a)) || ~isempty(strfind(rep, s52b));
nAD = sum(strcmp(tcell(EF.detection), 'ASSERTABLE-DETECT'));
nND = sum(strcmp(tcell(EF.detection), 'NOT-DETERMINABLE'));
sAD = sprintf('ASSERTABLE-DETECT = %d', nAD);
sND = sprintf('NOT-DETERMINABLE = %d', nND);
c5 = ~isempty(strfind(rep, sAD)) && ~isempty(strfind(rep, sND)) ...
    && (height(EF) == 48) && ~isempty(strfind(rep, '48 rows'));
p = c1 && c2 && c3 && c4 && c5;
n = sprintf(['CSV-derived spots in report: GIS-Q0-51 ''%s'' %d; ''%s'' %d; ''%s'' %d; ' ...
    '''%d x 52G PASS'' %d; effectiveness 48-row 24/24 ''%s''/''%s'' %d (report-vs-CSV only)'], ...
    sPick, c1, sF, c2, sP, c3, n52, c4, sAD, sND, c5);
end

function [p, n] = pIEC(DU, rep)
pats = {'IEC compliant', 'IEC-compliant', 'IEC 60909', 'fully realistic', ...
    'exact plant settings', 'actual relay settings'};
repL = lower(rep);
hitR = {};
for k = 1:numel(pats)
    if ~isempty(strfind(repL, lower(pats{k})))
        hitR{end + 1} = pats{k}; %#ok<AGROW>
    end
end
hitD = table_has_ci(DU, 'iec');
p = isempty(hitR) && ~hitD;
if p
    n = 'zero IEC (case-insensitive) in duty table; zero affirmative compliance-claim patterns in report';
else
    n = sprintf('report hits {%s}; duty IEC %d', strjoin(hitR, '; '), hitD);
end
end

function tf = table_has_ci(D, pat)
patL = lower(pat);
tf = ~isempty(strfind(lower(strjoin(D.Properties.VariableNames, '|')), patL));
if tf, return; end
for k = 1:numel(D.Properties.VariableNames)
    col = D.(D.Properties.VariableNames{k});
    if iscell(col)
        for i = 1:numel(col)
            vv = col{i};
            if (ischar(vv) || isstring(vv)) && ~isempty(strfind(lower(char(vv)), patL))
                tf = true; return;
            end
        end
    elseif ischar(col) || isstring(col)
        if ~isempty(strfind(lower(char(col)), patL)), tf = true; return; end
    end
end
end

function [p, n] = pFreeze(root, prodDir)
fp = fullfile(root, 'PHASE3_FINAL_REPORT.md');
d = dir(fp);
if numel(d) ~= 1 || d.isdir
    error('phase5b_gate:missing', 'PHASE3_FINAL_REPORT.md missing.');
end
okSize = (d.bytes == 45504);
sp = fullfile(prodDir, 'sha256.txt');
if exist(sp, 'file') ~= 2
    error('phase5b_gate:missing', 'production sha256.txt missing: %s', sp);
end
lines = strsplit(strtrim(fileread(sp)), char(10));
lines = lines(~cellfun(@isempty, strtrim(lines)));
okN = (numel(lines) == 7);
bad = 0;
for k = 1:numel(lines)
    ln = strtrim(lines{k});
    sp1 = strfind(ln, ' ');
    if isempty(sp1)
        bad = bad + 1; continue;
    end
    expH = ln(1:sp1(1) - 1);
    fname = strtrim(ln(sp1(end) + 1:end));
    fpp = fullfile(prodDir, fname);
    if exist(fpp, 'file') ~= 2
        bad = bad + 1; continue;
    end
    if ~strcmp(sha256file(fpp), lower(expH))
        bad = bad + 1;
    end
end
p = okSize && okN && (bad == 0);
n = sprintf('PHASE3_FINAL_REPORT.md %d bytes (expect 45504) %d; production sha256 %d/7 verify (mismatches %d)', ...
    d.bytes, okSize, numel(lines) - bad, bad);
end

function [p, n] = bRegistry(RG)
if height(RG) ~= 33
    p = false; n = sprintf('registry %d rows (expect 33)', height(RG)); return;
end
lay = tcell(RG.layer);
nS = sum(strcmp(lay, 'STUDY')); nP = sum(strcmp(lay, 'PHYSICAL'));
did = tcell(RG.device_id);
hasBL = any(strcmp(did, 'GEN-51-SIEMENS-BL'));
has52 = any(strcmp(did, 'GEN-52G'));
p = (nS == 7) && (nP == 26) && hasBL && has52;
n = sprintf('registry 33 rows: STUDY %d (expect 7) + PHYSICAL %d (expect 26); BL %d; 52G %d', nS, nP, hasBL, has52);
end

function [p, n] = bNo2000(raws, RG, ST, RC, MX)
hRaw = 0;
for k = 1:numel(raws)
    hRaw = hRaw + numel(strfind(raws{k}, '2000/1'));
end
nTab = 0;
if any(double(RG.ct_ratio) == 2000, 'all'), nTab = nTab + 1; end
if any(double(ST.ct_ratio) == 2000, 'all'), nTab = nTab + 1; end
if any(double(RC.CT_ratio) == 2000, 'all'), nTab = nTab + 1; end
if any(double(MX.ct_down) == 2000, 'all') || any(double(MX.ct_up) == 2000, 'all'), nTab = nTab + 1; end
p = (hRaw == 0) && (nTab == 0);
n = sprintf('''2000/1'' raw hits in 10 CSVs: %d (expect 0); ct==2000 tables hit: %d (expect 0; rated_A 2000 never counted)', hRaw, nTab);
end

function [p, n] = bDT(ST, RG, EF)
ids = tcell(ST.device_id);
bl = ST(strcmp(ids, 'GEN-51-SIEMENS-BL'), :);
if height(bl) ~= 1
    p = false; n = 'settings BL row not unique-present'; return;
end
cCurve = strcmp(bl.curve{1}, 'DT-??');
cTms = isnan(double(bl.tms));
cBasis = ~isempty(strfind(bl.basis{1}, '??'));
cVal = ~isempty(strfind(bl.validation{1}, '??'));
cProv = ~isempty(strfind(bl.provenance{1}, 'USER_ASSERTED'));
rdid = tcell(RG.device_id);
rbl = RG(strcmp(rdid, 'GEN-51-SIEMENS-BL'), :);
cReg = (height(rbl) == 1) && strcmp(rbl.curve{1}, 'DT-??');
bf = tcell(EF.backup_function);
sel = contains(bf, 'SIEMENS');
if ~any(sel)
    p = false; n = 'no SIEMENS backup rows in effectiveness'; return;
end
bt = double(EF.backup_time_s(sel));
cNaN = all(isnan(bt));
nd = tcell(EF.not_determinable(sel));
cReason = true;
for k = 1:numel(nd)
    if isempty(strfind(nd{k}, '??')), cReason = false; break; end
end
p = cCurve && cTms && cBasis && cVal && cProv && cReg && cNaN && cReason;
n = sprintf(['BL DT-?? curve %d + NaN-tms %d + ?? basis/val %d/%d + USER_ASSERTED %d + registry DT-?? %d; ' ...
    'SIEMENS backup NaN %d/%d + ?? reason %d'], ...
    cCurve, cTms, cBasis, cVal, cProv, cReg, sum(isnan(bt)), numel(bt), cReason);
end

function [p, n] = bEffectiveness(EF, rep)
