    p = false; n = sprintf('duty %d rows (expect 81)', height(DU)); return;
end
is52 = strcmp(tcell(DU.breaker_ref), '52G') & strcmp(tcell(DU.verdict), 'PASS');
n52 = sum(is52);
cRate = all(abs(double(DU.rating_kA(is52)) - 100) < 1e-12);
hit = DU(strcmp(tcell(DU.location), 'F1') & strcmp(tcell(DU.breaker_ref), '52G') ...
    & strcmp(tcell(DU.fault_type), 'LLL') & strcmp(tcell(DU.caseID), 'LF360_GAT_OUT'), :);
