n = sprintf('52G PASS %d/40 rating-100 %d; F1-LLL %.4f kA PASS %d; report 52G line %d', ...
    n52, cRate, double(hit.I_sym_kA), cLive, cRep);
end

function [p, n] = bV1untouched(v1Dir)
sp = fullfile(v1Dir, 'sha256.txt');
if exist(sp, 'file') ~= 2
    error('phase5b_gate:missing', 'v1 sha256.txt missing: %s', sp);
end
lines = strsplit(strtrim(fileread(sp)), char(10));
lines = lines(~cellfun(@isempty, strtrim(lines)));
if numel(lines) ~= 11
    p = false; n = sprintf('v1 sha256.txt has %d lines (expect 11)', numel(lines)); return;
end
bad = 0;
for k = 1:numel(lines)
    ln = strtrim(lines{k});
    sp1 = strfind(ln, ' ');
    if isempty(sp1)
        bad = bad + 1; continue;
    end
    expH = ln(1:sp1(1) - 1);
    fname = strtrim(ln(sp1(end) + 1:end));
    fp = fullfile(v1Dir, fname);
    if exist(fp, 'file') ~= 2
        bad = bad + 1; continue;
    end
    if ~strcmp(sha256file(fp), lower(expH))
        bad = bad + 1;
    end
end
p = (bad == 0);
n = sprintf('v1 sha256 recompute-verify 11/11 lines (mismatches: %d)', bad);
end

function hex = sha256file(path)
md = java.security.MessageDigest.getInstance('SHA-256');
jpath = java.io.File(path).toPath();
md.update(java.nio.file.Files.readAllBytes(jpath));
dig = md.digest();
bi = java.math.BigInteger(1, dig);
hex = char(bi.toString(16));
hex = [repmat('0', 1, 64 - numel(hex)) hex];
end

