    a = 0;  % fixed 5 A retained sensitive case (load-independent)
elseif strncmp(id, 'GEN-', 4)
    a = 14309;  % generator max operating current (ledger GEN-Imax-14309)
elseif strncmp(id, 'GSUT-HV', 7)
